return ['domain'=>NULL,'plural-forms'=>'nplurals=1; plural=0;','language'=>'id_ID','project-id-version'=>'TranslatePress Multilingual','pot-creation-date'=>'2026-10-13T10:48:01+03:00','po-revision-date'=>'2026-10-13T10:48:01+03:00','x-generator'=>'TranslatePress build (community + OpenRouter), 2026-10-13','messages'=>['TranslatePress - DEV'=>'TranslatePress - DEV','https://translatepress.com/'=>'https://translatepress.com/','Experience a better way of translating your WordPress site using a visual front-end translation editor, with full support for WooCommerce and site builders.'=>'Rasakan cara yang lebih baik untuk menerjemahkan situs WordPress Anda menggunakan editor terjemahan visual front-end, dengan dukungan penuh untuk WooCommerce dan pembuat situs.','Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban'=>'Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban','https://cozmoslabs.com/'=>'https://cozmoslabs.com/','Active'=>'Aktif','The inactive languages will still be visible and active for the admin. For other users they won\'t be visible in the language switchers and won\'t be accessible either.'=>'Bahasa yang tidak aktif akan tetap terlihat dan aktif untuk admin. Bagi pengguna lain, bahasa tersebut tidak akan terlihat di pengalih bahasa dan juga tidak dapat diakses.','unknown'=>'tidak diketahui','<strong>Extra Languages add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Pengaya Extra Languages</strong> memerlukan TranslatePress versi %1$s atau lebih tinggi. Anda saat ini menggunakan versi %2$s. Mohon perbarui TranslatePress untuk mengaktifkan fitur ini.','Dismiss this notice.'=>'Tutup pemberitahuan ini.','Post Slug'=>'Slug Pos','URL Slugs Translation'=>'Terjemahan Slug URL','Slugs'=>'Slug','Taxonomy Slugs'=>'Slug Taksonomi','Search Taxonomy Slugs'=>'Cari Slug Taksonomi','Taxonomy Slug'=>'Slug Taksonomi','Translation'=>'Terjemahan','Term Slugs'=>'Slug Istilah','Search Term Slugs'=>'Cari Slug Istilah','Term Slug'=>'Slug Istilah','Taxonomy'=>'Taksonomi','Filter by Taxonomy'=>'Filter menurut taksonomi','Post Slugs'=>'Slug Pos','Search Post Slugs'=>'Cari Slug Pos','Post ID'=>'ID Pos','Post Type'=>'Jenis Pos','Filter by Post Type'=>'Filter berdasarkan Jenis Pos','Published'=>'Diterbitkan','Any Post Status'=>'Status Pos Apa Saja','Post Type Base Slugs'=>'Slug Dasar Tipe Pos','Post Type Base Slug'=>'Slug Dasar Tipe Pos','Search Post Type Base Slugs'=>'Cari Slug Dasar Tipe Pos','WooCommerce Slugs'=>'Slug WooCommerce','WooCommerce Slug'=>'Slug WooCommerce','Search WooCommerce Slugs'=>'Cari Slug WooCommerce','Automatic and manual slug translation changes performed when <strong>TranslatePress - Multilingual</strong> 2.8.4 was active had to be removed because of some issues with that version. All slug translations from before that version are now in use. Thank you for understanding!'=>'Perubahan terjemahan slug otomatis dan manual yang dilakukan saat <strong>TranslatePress - Multilingual</strong> 2.8.4 aktif harus dihapus karena beberapa masalah pada versi tersebut. Semua terjemahan slug dari sebelum versi itu sekarang digunakan. Terima kasih atas pengertian Anda!','If you absolutely need them, the removed translations can be found in tables trp_slug_original_obsolete and trp_slug_translation_obsolete.'=>'Jika Anda benar-benar membutuhkannya, terjemahan yang dihapus dapat ditemukan di tabel trp_slug_original_obsolete dan trp_slug_translation_obsolete.','(inactive)'=>'(tidak aktif)','Other Slugs'=>'Slug Lainnya','Search Other Slugs'=>'Cari Slug Lainnya','Automatic User Language Detection'=>'Deteksi Otomatis Bahasa Pengguna','Invalid language code'=>'Kode bahasa tidak valid','We\'ve detected you might be speaking a different language. Do you want to change to:'=>'Kami mendeteksi Anda mungkin berbicara dalam bahasa lain. Apakah Anda ingin mengubah ke:','Change Language'=>'Ubah Bahasa','Close and do not switch language'=>'Tutup dan jangan ganti bahasa','First by browser language, then IP address (recommended)'=>'Pertama berdasarkan bahasa browser, lalu alamat IP (disarankan)','First by IP address, then by browser language'=>'Pertama berdasarkan alamat IP, lalu bahasa browser','Only by browser language'=>'Hanya berdasarkan bahasa browser','Only by IP address'=>'Hanya berdasarkan alamat IP','A popup appears asking the user if they want to be redirected'=>'Sebuah pop-up muncul menanyakan pengguna apakah mereka ingin dialihkan','Redirect directly (*not recommended)'=>'Alihkan langsung (*tidak disarankan)','Pop-up window over the content'=>'Jendela pop-up di atas konten','Hello bar before the content'=>'Bilah hello sebelum konten','Automatic User Language Detection requires a newer version of TranslatePress to use its visual settings interface. The legacy settings form will remain available until TranslatePress is updated.'=>'Deteksi Bahasa Pengguna Otomatis memerlukan versi TranslatePress yang lebih baru untuk menggunakan antarmuka pengaturan visualnya. Formulir pengaturan lama akan tetap tersedia hingga TranslatePress diperbarui.','Update TranslatePress'=>'Perbarui TranslatePress','WARNING. Cannot determine your language preference based on your current IP.<br>This is most likely because the website is on a local environment.'=>'PERINGATAN. Tidak dapat menentukan preferensi bahasa Anda berdasarkan IP Anda saat ini.<br>Ini kemungkinan besar karena situs web berada di lingkungan lokal.','Permission denied.'=>'Izin ditolak.','Invalid nonce.'=>'Nonce tidak valid.','Invalid settings.'=>'Pengaturan tidak valid.','Settings saved.'=>'Pengaturan disimpan.','Go to <a href="%s" target="_self">Advanced</a> tab to change this feature\'s settings'=>'Buka tab <a href="%s" target="_self">Lanjutan</a> untuk mengubah pengaturan fitur ini','Website language selector'=>'Pemilih bahasa situs web','Change language'=>'Ubah bahasa','Available languages'=>'Bahasa yang tersedia','Please enter your DeepL API key.'=>'Silakan masukkan kunci API DeepL Anda.','DeepL'=>'DeepL','Bad request. There was an error accessing the DeepL API.'=>'Permintaan tidak valid. Terjadi kesalahan saat mengakses DeepL API.','The API key entered is invalid.'=>'Kunci API yang dimasukkan tidak valid.','The API resource could not be found.'=>'Sumber daya API tidak dapat ditemukan.','The request size is too large.'=>'Ukuran permintaan terlalu besar.','The request is too long.'=>'Permintaan terlalu panjang.','Too many requests. Please try again later.'=>'Terlalu banyak permintaan. Silakan coba lagi nanti.','Your translation quota has been reached.'=>'Kuota terjemahan Anda telah tercapai.','We could not process your request. Please try again later.'=>'Kami tidak dapat memproses permintaan Anda. Silakan coba lagi nanti.','There is an error on the DeepL service and your request could not be processed.'=>'Terjadi kesalahan pada layanan DeepL dan permintaan Anda tidak dapat diproses.','DeepL API Type'=>'Jenis API DeepL','Pro'=>'Pro','Free'=>'Gratis','Select the type of DeepL API you want to use.'=>'Pilih jenis API DeepL yang ingin Anda gunakan.','DeepL API Key'=>'Kunci API DeepL','Visit <a href="%s" target="_blank">this link</a> to see how you can set up an API key and control API costs.'=>'Kunjungi <a href="%s" target="_blank">tautan ini</a> untuk melihat cara menyiapkan kunci API dan mengontrol biaya API.','No Active License Detected for this website.'=>'Tidak ada lisensi aktif yang terdeteksi untuk situs web ini.','Enter your license key'=>'Masukkan kunci lisensi Anda',' Or %1$spurchase one here%2$s'=>' Atau %1$sbeli di sini%2$s','Different Domain per Language'=>'Domain Berbeda per Bahasa','View Docs'=>'Lihat Dokumentasi','Assign different domains or subdomains to each language. When visitors access these domains, TranslatePress loads the appropriate language translation directly without redirecting.'=>'Tetapkan domain atau subdomain yang berbeda untuk setiap bahasa. Ketika pengunjung mengakses domain ini, TranslatePress memuat terjemahan bahasa yang sesuai secara langsung tanpa pengalihan.','Example: %1$s for English, %2$s for Spanish, %3$s for French.'=>'Contoh: %1$s untuk bahasa Inggris, %2$s untuk bahasa Spanyol, %3$s untuk bahasa Prancis.','Before enabling:'=>'Sebelum mengaktifkan:','Ensure your domains are registered, pointed to your server, and have SSL certificates configured.'=>'Pastikan domain Anda terdaftar, diarahkan ke server Anda, dan memiliki sertifikat SSL yang dikonfigurasi.','Domain'=>'Domain','Map this language to a different domain or sub-domain.'=>'Petakan bahasa ini ke domain atau sub-domain yang berbeda.','https://example.com'=>'https://example.com','Prefill with current domain'=>'Isi otomatis dengan domain saat ini','Check DNS'=>'Periksa DNS','Checking DNS...'=>'Memeriksa DNS...','DNS is correctly configured!'=>'DNS sudah dikonfigurasi dengan benar!','DNS check failed. Please verify your domain configuration.'=>'Pemeriksaan DNS gagal. Silakan verifikasi konfigurasi domain Anda.','This domain is already assigned to another language.'=>'Domain ini sudah ditetapkan ke bahasa lain.','<strong>Different Domain per Language add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Different Domain per Language add-on</strong> memerlukan TranslatePress versi %1$s atau lebih tinggi. Saat ini Anda menggunakan versi %2$s. Silakan perbarui TranslatePress untuk mengaktifkan fitur ini.','Note: This option is disabled when Different Domain for Language addon is active.'=>'Catatan: Opsi ini dinonaktifkan saat Different Domain for Language addon aktif.','Different Domain per Language: Domain is required when domain mapping is enabled. The toggle has been disabled for languages with empty domains.'=>'Different Domain per Language: Domain diperlukan saat pemetaan domain diaktifkan. Tombol alih telah dinonaktifkan untuk bahasa dengan domain kosong.','Different Domain per Language: The same domain cannot be assigned to multiple languages. The toggle has been disabled for duplicate domains.'=>'Different Domain per Language: Domain yang sama tidak dapat ditetapkan ke beberapa bahasa. Tombol alih telah dinonaktifkan untuk domain duplikat.','Different Domain per Language: A language domain cannot be the same as the main site URL. The toggle has been disabled for the matching domain.'=>'Different Domain per Language: Domain bahasa tidak boleh sama dengan URL situs utama. Tombol alih telah dinonaktifkan untuk domain yang cocok.','Please enter a domain.'=>'Silakan masukkan domain.','Invalid domain format.'=>'Format domain tidak valid.','Could not reach domain: %s'=>'Gagal mengakses domain: %s','Domain is reachable!'=>'Domain dapat dijangkau!','Domain returned HTTP status %d.'=>'Domain mengembalikan status HTTP %d.','Limit this menu item to the following languages'=>'Batasi item menu ini ke bahasa berikut','All Languages'=>'Semua Bahasa','Translator'=>'Penerjemah',' TranslatePress Settings'=>' Pengaturan TranslatePress','Allow this user to translate the website.'=>'Izinkan pengguna ini untuk menerjemahkan situs web.','Translate Site'=>'Terjemahkan Situs','Add-On'=>'Pengaya','Deactivate'=>'Nonaktifkan','Activate'=>'Aktifkan','Installing...'=>'Menginstal...','This add-on can not be activated back without a valid license. Are you sure you want to deactivate it?'=>'Pengaya ini tidak dapat diaktifkan kembali tanpa lisensi yang valid. Apakah Anda yakin ingin menonaktifkannya?','Documentation'=>'Dokumentasi','A valid license is required to activate add-ons.'=>'Lisensi yang valid diperlukan untuk mengaktifkan pengaya.','Activate all'=>'Aktifkan semua','Add-ons can not be activated back without a valid license. Are you sure you want to deactivate them?'=>'Pengaya tidak dapat diaktifkan kembali tanpa lisensi yang valid. Apakah Anda yakin ingin menonaktifkannya?','Deactivate all'=>'Nonaktifkan semua','%1$sAdd-ons settings saved successfully%2$s'=>'%1$sPengaturan pengaya berhasil disimpan%2$s','Date format'=>'Format tanggal','Customize the date formatting per each translated language.<br/>Leave empty for default WP setting or see more information <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">here</a>'=>'Sesuaikan format tanggal untuk setiap bahasa yang diterjemahkan.<br/>Biarkan kosong untuk pengaturan default WP atau lihat informasi selengkapnya <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">di sini</a>','To edit an existing TranslatePress language, input the language code and fill in only the columns you want to overwrite (e.g. Language name, Flag).<br>You can also add new custom languages. They will be available under General settings, All Languages list, where the URL slug can be edited.'=>'Untuk mengedit bahasa TranslatePress yang sudah ada, masukkan kode bahasa dan isi hanya kolom yang ingin Anda timpa (mis. Nama bahasa, Bendera).<br>Anda juga dapat menambahkan bahasa kustom baru. Bahasa-bahasa tersebut akan tersedia di bawah Pengaturan Umum, daftar Semua Bahasa, di mana slug URL dapat diedit.','For custom flag, first upload the image in media library then paste the URL.<br>Changing or deleting a custom language will impact translations and site URL\'s.<br>The Language code and the ISO Code should contain only alphabetical values, numerical values, "-" and "_".<br>The ISO Codes can be found on <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO Codes</a> and <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL Target Codes</a>.'=>'Untuk bendera kustom, unggah gambar terlebih dahulu ke pustaka media lalu tempel URL-nya.<br>Mengubah atau menghapus bahasa kustom akan memengaruhi terjemahan dan URL situs.<br>Kode bahasa dan kode ISO hanya boleh mengandung karakter alfabet, karakter numerik, "-" dan "_".<br>Kode ISO dapat ditemukan di <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Kode ISO Google</a> dan <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">Kode Target DeepL</a>.','Language code'=>'Kode bahasa','Language name'=>'Nama bahasa','Native name'=>'Nama asli','ISO Code'=>'Kode ISO','Flag URL'=>'URL bendera','Text RTL'=>'Teks RTL','Custom language'=>'Bahasa kustom','Disable bundled plugin translations'=>'Nonaktifkan terjemahan bawaan plugin','By default, TranslatePress ships its own translation files in <code>wp-content/plugins/translatepress/languages/</code> and forces WordPress to use them instead of the language packs installed automatically from translate.wordpress.org.<br/>Enable this option to disable that override. WordPress will then load the community language pack from <code>wp-content/languages/plugins/</code> (if present) and fall back to the bundled files only when no pack is available.'=>'Secara default, TranslatePress menyertakan file terjemahannya sendiri di <code>wp-content/plugins/translatepress/languages/</code> dan memaksa WordPress untuk menggunakannya, bukan paket bahasa yang diinstal secara otomatis dari translate.wordpress.org.<br/>Aktifkan opsi ini untuk menonaktifkan penimpaan tersebut. WordPress kemudian akan memuat paket bahasa komunitas dari <code>wp-content/languages/plugins/</code> (jika ada) dan kembali ke file bawaan hanya ketika tidak ada paket yang tersedia.','Disable dynamic translation'=>'Nonaktifkan terjemahan dinamis','It disables detection of strings displayed dynamically using JavaScript. <br/>Strings loaded via a server side AJAX call will still be translated.'=>'Menonaktifkan deteksi string yang ditampilkan secara dinamis menggunakan JavaScript. <br/>String yang dimuat melalui panggilan AJAX sisi server akan tetap diterjemahkan.','Disable translation for gettext strings'=>'Nonaktifkan terjemahan untuk string gettext','Gettext Strings are strings outputted by themes and plugins. <br> Translating these types of strings through TranslatePress can be unnecessary if they are already translated using the .po/.mo translation file system.<br>Enabling this option can improve the page load performance of your site in certain cases. The disadvantage is that you can no longer edit gettext translations using TranslatePress, nor benefit from automatic translation on these strings.'=>'String Gettext adalah string yang dihasilkan oleh tema dan plugin. <br> Menerjemahkan jenis string ini melalui TranslatePress mungkin tidak diperlukan jika sudah diterjemahkan menggunakan sistem file terjemahan .po/.mo.<br>Mengaktifkan opsi ini dapat meningkatkan performa pemuatan halaman situs Anda dalam kasus tertentu. Kekurangannya adalah Anda tidak lagi dapat mengedit terjemahan gettext menggunakan TranslatePress, maupun memanfaatkan penerjemahan otomatis pada string ini.','Gettext Strings translation is disabled'=>'Terjemahan string Gettext dinonaktifkan','To enable it go to '=>'Untuk mengaktifkannya, buka ','TranslatePress->Advanced Settings->Debug->Disable translation for gettext strings'=>'TranslatePress->Pengaturan Lanjutan->Debug->Nonaktifkan terjemahan untuk string Gettext',' and uncheck the Checkbox.'=>' dan hapus centang pada kotak centang.','Dismiss'=>'Tutup','Exclude translated links from sitemap'=>'Kecualikan tautan terjemahan dari sitemap','Do not include translated links in sitemaps generated by SEO plugins.<br/>Requires <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> SEO Pack Add-on</a> to be installed and activated.'=>'Jangan sertakan tautan terjemahan dalam sitemaps yang dihasilkan oleh plugin SEO.<br/>Memerlukan <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> Add-on SEO Pack</a> untuk diinstal dan diaktifkan.','Disable post container tags for post title'=>'Nonaktifkan tag kontainer pos untuk judul pos','It disables search indexing the post title in translated languages.<br/>Useful when the title of the post doesn\'t allow HTML thus breaking the page.'=>'Ini menonaktifkan pengindeksan pencarian judul pos dalam bahasa terjemahan.<br/>Berguna ketika judul pos tidak mengizinkan HTML sehingga merusak halaman.','Disable post container tags for post content'=>'Nonaktifkan tag kontainer pos untuk konten pos','It disables search indexing the post content in translated languages.<br/>Useful when the content of the post doesn\'t allow HTML thus breaking the page.'=>'Ini menonaktifkan pengindeksan pencarian konten pos dalam bahasa terjemahan.<br/>Berguna ketika konten pos tidak mengizinkan HTML sehingga merusak halaman.','Do not translate certain paths'=>'Jangan terjemahkan jalur tertentu','Choose what paths can be translated. Supports wildcard at the end of the path.<br>For example, to exclude https://example.com/some/path you can either use the rule /some/path/ or /some/*.<br>Enter each rule on it\'s own line. To exclude the home page use {{home}}.'=>'Pilih jalur mana yang dapat diterjemahkan. Mendukung wildcard di akhir jalur.<br>Misalnya, untuk mengecualikan https://example.com/some/path Anda dapat menggunakan aturan /some/path/ atau /some/*.<br>Masukkan setiap aturan pada barisnya sendiri. Untuk mengecualikan halaman beranda gunakan {home}.','Exclude Paths From Translation'=>'Kecualikan Jalur Dari Penerjemahan','Translate Only Certain Paths'=>'Terjemahkan Hanya Jalur Tertentu','Enable the hreflang x-default tag for language:'=>'Aktifkan tag hreflang x-default untuk bahasa:','Enables the hreflang="x-default" for an entire language. See documentation for more details.'=>'Mengaktifkan hreflang="x-default" untuk sebuah bahasa secara keseluruhan. Lihat dokumentasi untuk detail lebih lanjut.','Translate numbers and numerals'=>'Terjemahkan angka dan numeral','Enable translation of numbers ( e.g. phone numbers)'=>'Aktifkan penerjemahan angka (mis. nomor telepon)','Selector'=>'Selektor','Exclude from dynamic translation'=>'Kecualikan dari penerjemahan dinamis','Do not dynamically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated using JavaScript.<br/>These strings will still be translated on the server side if possible.'=>'Tidak menerjemahkan string secara dinamis yang ditemukan dalam node html yang cocok dengan selektor ini.<br>Mengecualikan semua turunan node HTML yang cocok dengan selektor ini dari penerjemahan menggunakan JavaScript.<br/>String ini akan tetap diterjemahkan di sisi server jika memungkinkan.','Gettext String'=>'String Gettext','Exclude Gettext Strings'=>'Kecualikan String Gettext','Exclude these strings from being translated as Gettext strings by TranslatePress. Leave the domain empty to take into account any Gettext string.<br/>Can still be translated through po/mo files.'=>'Kecualikan string ini agar tidak diterjemahkan sebagai string Gettext oleh TranslatePress. Biarkan domain kosong untuk memperhitungkan semua string Gettext apa pun.<br/>Masih dapat diterjemahkan melalui file po/mo.','Exclude selectors only from automatic translation'=>'Kecualikan selektor hanya dari terjemahan otomatis','Do not automatically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being automatically translated.<br>Manual translation of these strings is still possible.'=>'Tidak menerjemahkan string secara otomatis yang ditemukan dalam node html yang cocok dengan selektor ini.<br>Mengecualikan semua turunan node HTML yang cocok dengan selektor ini dari penerjemahan otomatis.<br>Penerjemahan manual string ini masih dimungkinkan.','Exclude selectors from translation'=>'Kecualikan selektor dari terjemahan','Do not translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated.<br>These strings cannot be translated manually nor automatically.'=>'Tidak menerjemahkan string yang ditemukan dalam node html yang cocok dengan selektor ini.<br>Mengecualikan semua turunan node HTML yang cocok dengan selektor ini dari penerjemahan.<br>String ini tidak dapat diterjemahkan secara manual maupun otomatis.','String'=>'String','Exclude strings from automatic translation'=>'Kecualikan string dari penerjemahan otomatis','Do not automatically translate these strings (ex. names, technical words...)<br>Paragraphs containing these strings will still be translated except for the specified part.'=>'Tidak menerjemahkan string ini secara otomatis (mis. nama, kata teknis...)<br>Paragraf yang memuat string ini akan tetap diterjemahkan kecuali bagian yang ditentukan.','Fix broken HTML'=>'Perbaiki HTML yang rusak','General attempt to fix broken or missing HTML on translated pages.<br/>'=>'Upaya umum untuk memperbaiki HTML yang rusak atau hilang pada halaman terjemahan.<br/>','Force slash at end of home url:'=>'Paksa garis miring di akhir home url:','Ads a slash at the end of the home_url() function'=>'Menambahkan garis miring di akhir fungsi home_url()','Show Both (recommended)'=>'Tampilkan Keduanya (disarankan)','Remove Country Locale'=>'Hapus Locale Negara','Remove Region Independent Locale'=>'Hapus Locale Independen Wilayah','Remove duplicate hreflang'=>'Hapus hreflang duplikat','Choose which hreflang tags will appear on your website.<br/>We recommend showing both types of hreflang tags as indicated by <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">Google documentation</a>.<br/>Removing Country Locale when having multiple Country Locales of the same language (ex. English UK and English US) will result in showing one hreflang tag with link to just one of the region locales for that language.'=>'Pilih tag hreflang mana yang akan muncul di situs web Anda.<br/>Kami menyarankan untuk menampilkan kedua jenis tag hreflang sebagaimana diindikasikan oleh <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">dokumentasi Google</a>.<br/>Menghapus Locale Negara ketika memiliki beberapa Locale Negara dari bahasa yang sama (mis. English UK dan English US) akan mengakibatkan ditampilkannya hanya satu tag hreflang dengan tautan ke salah satu locale wilayah untuk bahasa tersebut.','Default (example: en-US, fr-CA, etc.)'=>'Default (contoh: en-US, fr-CA, dll.)','Regional (example: en, fr, es, etc.)'=>'Regional (contoh: en, fr, es, dll.)','HTML Lang Attribute Format'=>'Format Atribut Lang HTML','Change lang attribute of the html tag to a format that includes country regional or not. <br>In HTML, the lang attribute (<html lang="en-US">)  should be used to  specify the language of text content so that the  browser can correctly display or process  your content (eg. for  hyphenation, styling, spell checking, etc).'=>'Ubah atribut lang pada tag html ke format yang menyertakan regional negara atau tidak. <br>Dalam HTML, atribut lang (<html lang="en-US">)  harus digunakan untuk  menentukan bahasa konten teks agar  browser dapat menampilkan atau memproses  konten Anda dengan benar (mis. untuk  pemenggalan kata, penataan gaya, pemeriksaan ejaan, dll).','Load legacy Language Switcher'=>'Muat pengalih bahasa lawas','Applies to all types of language switchers (floating, shortcode, and menu). When enabled, the site will revert to using the original Language Switcher configured in the General Settings tab, replacing the new customizable version. Your existing switcher settings will remain saved, but they will be ignored while this option is active.'=>'Berlaku untuk semua jenis pengalih bahasa (melayang, shortcode, dan menu). Jika diaktifkan, situs akan kembali menggunakan pengalih bahasa asli yang dikonfigurasi di tab Pengaturan Umum, menggantikan versi baru yang dapat disesuaikan. Pengaturan pengalih bahasa yang ada akan tetap tersimpan, tetapi akan diabaikan selama opsi ini aktif.','Load legacy SEO Pack Add-On'=>'Muat add-on SEO Pack lawas','In case the recent migration to the new slug rewrite is causing trouble, set this to Yes to use the old method <br> Please <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">open a support ticket</a> letting us know of the issues you are having.'=>'Jika migrasi terbaru ke penulisan ulang slug baru menimbulkan masalah, atur ini ke Ya untuk menggunakan metode lama <br> Silakan <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">buka tiket dukungan</a> untuk memberi tahu kami masalah yang Anda alami.','Manual Translation Only'=>'Hanya terjemahan manual','TranslatePress pro-actively scans and saves strings in the database when users access translated pages. <br>This setting disables this functionality and only allows translation and string saving when inside the Translation Editor. <br>Also disables machine translation outside the Translation Editor, giving you better control over character spending, by translating only the pages you visit in the Translation Editor.'=>'TranslatePress secara proaktif memindai dan menyimpan string dalam basis data ketika pengguna mengakses halaman terjemahan. <br>Pengaturan ini menonaktifkan fungsionalitas ini dan hanya mengizinkan penerjemahan dan penyimpanan string saat berada di dalam Editor Terjemahan. <br>Juga menonaktifkan penerjemahan mesin di luar Editor Terjemahan, memberi Anda kontrol yang lebih baik atas pengeluaran karakter, dengan hanya menerjemahkan halaman yang Anda kunjungi di Editor Terjemahan.','Open language switcher only on click'=>'Buka pengalih bahasa hanya dengan klik','Open the language switcher shortcode by clicking on it instead of hovering.<br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. This will affect only the shortcode language switcher.'=>'Buka shortcode pengalih bahasa dengan mengkliknya, bukan dengan mengarahkan kursor.<br> Tutup dengan mengkliknya, mengklik di mana saja pada layar, atau dengan menekan tombol escape. Ini hanya akan memengaruhi shortcode pengalih bahasa.','Show opposite language in the language switcher'=>'Tampilkan bahasa berlawanan di pengalih bahasa','Transforms the language switcher into a button showing the other available language, not the current one.<br> Only works when there are exactly two languages, the default one and a translation one.<br>This will affect the shortcode language switcher and floating language switcher as well.<br> To achieve this in menu language switcher go to Appearance->Menus->Language Switcher and select Opposite Language.'=>'Mengubah pengalih bahasa menjadi tombol yang menampilkan bahasa lain yang tersedia, bukan bahasa saat ini.<br> Hanya berfungsi ketika terdapat tepat dua bahasa, bahasa default dan bahasa terjemahan.<br>Ini akan memengaruhi shortcode pengalih bahasa dan pengalih bahasa melayang juga.<br> Untuk mencapai ini pada pengalih bahasa menu, buka Tampilan->Menu->Pengalih Bahasa dan pilih Bahasa Berlawanan.','TranslatePress gettext database optimization failed.'=>'Pengoptimalan database gettext TranslatePress gagal.','Retry'=>'Coba Lagi','TranslatePress needs to optimize its gettext database tables. Back up the database, then <a href="%s">start the optimization</a>.'=>'TranslatePress perlu mengoptimalkan tabel database gettext. Cadangkan database, lalu <a href="%s">mulai pengoptimalan</a>.','Pending gettext database optimization'=>'Pengoptimalan database gettext tertunda','Optimize TranslatePress database tables'=>'Optimalkan tabel basis data TranslatePress','<a href="%s">Click here</a> to access the database optimization tool.'=>'<a href="%s">Klik di sini</a> untuk mengakses alat optimasi basis data.','It helps remove possible duplicate translations, clear unnecessary data and repair possible metadata issues.'=>'Ini membantu menghapus kemungkinan duplikat terjemahan, membersihkan data yang tidak perlu, dan memperbaiki kemungkinan masalah metadata.','<a href="%s" target="_blank">Here</a> you can observe the last 5 SQL errors relevant to TranslatePress if they exist.'=>'<a href="%s" target="_blank">Di sini</a> Anda dapat melihat 5 error SQL terakhir yang relevan dengan TranslatePress jika ada.','Troubleshooting'=>'Penyelesaian Masalah','Exclude Gettext strings'=>'Kecualikan string Gettext','Debug'=>'Debug','Custom languages'=>'Bahasa kustom','Miscellaneous options'=>'Opsi lainnya','Language Switcher'=>'Pengalih Bahasa','Exclude strings & pages'=>'Kecualikan string & halaman','Automatic Translation Memory'=>'Memori Terjemahan Otomatis','Serve same translation for similar text. The strings need to have a percentage of 95% similarity.<br>Helps prevent losing existing translation when correcting typos or making minor adjustments to the original text. <br>If a translation already exists for a very similar original string, it will automatically be used for the current original string.<br>Does not work when making changes to a text that is part of a translation block unless the new text is manually merged again in a translation block.<br>Each string needs to have a minimum of 50 characters.'=>'Gunakan terjemahan yang sama untuk teks yang mirip. String harus memiliki tingkat kemiripan 95%.<br>Membantu mencegah kehilangan terjemahan yang ada saat memperbaiki kesalahan ketik atau melakukan penyesuaian kecil pada teks asli. <br>Jika terjemahan sudah ada untuk string asli yang sangat mirip, maka akan otomatis digunakan untuk string asli saat ini.<br>Tidak berfungsi saat mengubah teks yang merupakan bagian dari blok terjemahan kecuali teks baru digabungkan kembali secara manual dalam blok terjemahan.<br>Setiap string harus memiliki minimal 50 karakter.','WARNING: This feature can negatively impact page loading times in secondary languages, particularly with large databases (for example websites with a lot of pages or products). If you experience slow loading times, disable this and try again.'=>'PERINGATAN: Fitur ini dapat berdampak negatif pada waktu muat halaman dalam bahasa sekunder, terutama dengan database besar (misalnya situs web dengan banyak halaman atau produk). Jika Anda mengalami waktu muat yang lambat, nonaktifkan ini dan coba lagi.','Fix missing dynamic content'=>'Perbaiki konten dinamis yang hilang','May help fix missing content inserted using JavaScript. <br> It shows dynamically inserted content in original language for a moment before the translation request is finished.'=>'Dapat membantu memperbaiki konten yang hilang yang disisipkan menggunakan JavaScript. <br> Menampilkan konten yang disisipkan secara dinamis dalam bahasa asli sesaat sebelum permintaan terjemahan selesai.','Filter Gettext wrapping from post content and title'=>'Saring pembungkus Gettext dari konten dan judul pos','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post content and post title. Does not affect previous post content. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Menyaring pembungkus gettext seperti #!trpst#trp-gettext dari semua konten pos dan judul pos yang diperbarui. Tidak memengaruhi konten pos sebelumnya. <br/><strong>Backup database disarankan sebelum mengaktifkannya.</strong>','Filter Gettext wrapping from post meta'=>'Saring pembungkus Gettext dari meta pos','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post meta. Does not affect previous post meta. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Menyaring pembungkus gettext seperti #!trpst#trp-gettext dari semua meta pos yang diperbarui. Tidak memengaruhi meta pos sebelumnya. <br/><strong>Backup database disarankan sebelum mengaktifkannya.</strong>','TranslatePress'=>'TranslatePress','Abilities for managing TranslatePress configuration.'=>'Kemampuan untuk mengelola konfigurasi TranslatePress.','Add a translation language'=>'Tambahkan bahasa terjemahan','Adds a translation language to TranslatePress. Enforces the same per-license limit as the settings UI.'=>'Menambahkan bahasa terjemahan ke TranslatePress. Menerapkan batas per lisensi yang sama seperti UI pengaturan.','WordPress locale code (e.g. fr_FR, de_DE).'=>'Kode lokal WordPress (misalnya fr_FR, de_DE).','Optional URL slug. Defaults to the ISO language code if omitted.'=>'Slug URL opsional. Default ke kode bahasa ISO jika tidak diisi.','Set TranslatePress license key'=>'Tetapkan kunci lisensi TranslatePress','Saves a TranslatePress license key and triggers a remote license check, mirroring the onboarding flow.'=>'Menyimpan kunci lisensi TranslatePress dan memicu pemeriksaan lisensi jarak jauh, meniru alur onboarding.','The license key to activate.'=>'Kunci lisensi yang akan diaktifkan.','Enable Automatic Translation'=>'Aktifkan Terjemahan Otomatis','Turns on Automatic Translation. A valid TranslatePress license is required only when the resolved engine is TranslatePress AI (mtapi); Google Translate and DeepL do not require one. If no engine is passed and none is configured, defaults to mtapi.'=>'Mengaktifkan Terjemahan Otomatis. Lisensi TranslatePress yang valid hanya diperlukan jika mesin yang digunakan adalah TranslatePress AI (mtapi); Google Translate dan DeepL tidak memerlukannya. Jika tidak ada mesin yang diberikan dan tidak ada yang dikonfigurasi, default ke mtapi.','Optional translation-engine slug to select (e.g. "mtapi", "google_translate_v2", "deepl"). When omitted, keeps the already-configured engine, or defaults to "mtapi" if none is configured.'=>'Slug mesin penerjemahan opsional untuk dipilih (mis. "mtapi", "google_translate_v2", "deepl"). Jika dihilangkan, mempertahankan mesin yang sudah dikonfigurasi, atau default ke "mtapi" jika tidak ada yang dikonfigurasi.','List configured languages'=>'Daftar bahasa yang dikonfigurasi','Returns the languages currently configured in TranslatePress, including the default language and per-language slug/publish state.'=>'Mengembalikan bahasa yang saat ini dikonfigurasi di TranslatePress, termasuk bahasa default serta slug dan status publikasi setiap bahasa.','List available language codes'=>'Daftar kode bahasa yang tersedia','Returns the full catalog of language codes TranslatePress recognizes, with their English names.'=>'Mengembalikan katalog lengkap kode bahasa yang dikenali TranslatePress, dengan nama dalam bahasa Inggris.','Remove a translation language'=>'Hapus bahasa terjemahan','Removes a configured translation language. The default language cannot be removed without first reassigning the default.'=>'Menghapus bahasa terjemahan yang telah dikonfigurasi. Bahasa default tidak dapat dihapus tanpa terlebih dahulu menetapkan ulang bahasa default.','Locale code of the language to remove.'=>'Kode locale bahasa yang akan dihapus.','Update a translation language'=>'Perbarui bahasa terjemahan','Replaces the slug and publish status of an already-configured translation language.'=>'Mengganti slug dan status publikasi bahasa terjemahan yang telah dikonfigurasi.','Locale code of the language to update.'=>'Kode locale bahasa yang akan diperbarui.','URL slug for this language.'=>'Slug URL untuk bahasa ini.','Whether this language is published on the front end.'=>'Apakah bahasa ini dipublikasikan di front end.','Set the default language'=>'Atur bahasa default','Promotes an already-configured language to be the site default. The previous default remains in the translation languages list.'=>'Menjadikan bahasa yang telah dikonfigurasi sebagai default situs. Bahasa default sebelumnya tetap berada dalam daftar bahasa terjemahan.','Locale code to promote to default. Must already be a configured translation language.'=>'Kode locale yang akan dijadikan default. Harus sudah merupakan bahasa terjemahan yang dikonfigurasi.','You do not have permission to manage TranslatePress settings.'=>'Anda tidak memiliki izin untuk mengelola pengaturan TranslatePress.','Invalid language code. Allowed characters: A-Z, a-z, 0-9, hyphen, underscore.'=>'Kode bahasa tidak valid. Karakter yang diizinkan: A-Z, a-z, 0-9, tanda hubung, garis bawah.','Language code "%s" is not recognized by TranslatePress.'=>'Kode bahasa "%s" tidak dikenali oleh TranslatePress.','Language "%s" is already configured.'=>'Bahasa "%s" sudah dikonfigurasi.','Your current license allows up to %d additional language(s). Upgrade or activate a Pro license to add more.'=>'Lisensi Anda saat ini mengizinkan hingga %d bahasa tambahan. Tingkatkan atau aktifkan lisensi Pro untuk menambah lebih banyak.','TranslatePress rejected the new language during settings sanitization.'=>'TranslatePress menolak bahasa baru selama sanitasi pengaturan.','Enabling Automatic Translation with the TranslatePress AI engine requires an active TranslatePress license. Activate a license first with translatepress/set-license-key, or pass a different engine (e.g. "google_translate_v2", "deepl").'=>'Mengaktifkan Terjemahan Otomatis dengan mesin TranslatePress AI memerlukan lisensi TranslatePress yang aktif. Aktifkan lisensi terlebih dahulu dengan translatepress/set-license-key, atau gunakan mesin lain (mis. "google_translate_v2", "deepl").','Your license key expired on %s.'=>'Kunci lisensi Anda kedaluwarsa pada %s.','Your license key has expired.'=>'Kunci lisensi Anda telah kedaluwarsa.','Your license key has been disabled.'=>'Kunci lisensi Anda telah dinonaktifkan.','Your TranslatePress license key is invalid or missing.'=>'Kunci lisensi TranslatePress Anda tidak valid atau hilang.','Your license key is disabled for this URL. Re-enable it from your TranslatePress account.'=>'Kunci lisensi Anda dinonaktifkan untuk URL ini. Aktifkan kembali dari akun TranslatePress Anda.','License key mismatch. The license you entered does not match the TranslatePress version you have installed.'=>'Kunci lisensi tidak cocok. Lisensi yang Anda masukkan tidak cocok dengan versi TranslatePress yang telah Anda instal.','Your license key has reached its activation limit.'=>'Kunci lisensi Anda telah mencapai batas aktivasi.','An error occurred while activating the license, please try again.'=>'Terjadi kesalahan saat mengaktifkan lisensi, silakan coba lagi.','Language "%s" is not currently configured.'=>'Bahasa "%s" saat ini tidak dikonfigurasi.','The default language cannot be removed. Set another language as default first.'=>'Bahasa default tidak dapat dihapus. Tetapkan bahasa lain sebagai default terlebih dahulu.','Slug is empty after sanitization. Use only URL-safe characters.'=>'Slug kosong setelah sanitasi. Gunakan hanya karakter yang aman untuk URL.','Language "%s" is not currently configured. Add it first with translatepress/add-language.'=>'Bahasa "%s" saat ini tidak dikonfigurasi. Tambahkan terlebih dahulu dengan translatepress/add-language.','The default language is always published and cannot be unpublished.'=>'Bahasa default selalu dipublikasikan dan tidak dapat dibatalkan publikasinya.','Slug "%1$s" is already in use by language "%2$s".'=>'Slug "%1$s" sudah digunakan oleh bahasa "%2$s".','TranslatePress rejected the new settings during sanitization.'=>'TranslatePress menolak pengaturan baru selama sanitasi.','Advanced'=>'Lanjutan','Are you sure you want to remove this item?'=>'Apakah Anda yakin ingin menghapus item ini?','Remove'=>'Hapus','Add'=>'Tambah','Select...'=>'Pilih...','An error occurred, please try again.'=>'Terjadi kesalahan, silakan coba lagi.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Kunci lisensi Anda dinonaktifkan untuk URL ini. Aktifkan kembali dari <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Kelola Situs.','<p><strong>License key mismatch.</strong> The license you entered doesn’t match the TranslatePress version you have installed.</p><p>Please check that you’ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>Kunci lisensi tidak cocok.</strong> Lisensi yang Anda masukkan tidak cocok dengan versi TranslatePress yang telah Anda pasang.</p><p>Silakan periksa bahwa Anda telah memasang versi yang benar untuk lisensi Anda dari akun TranslatePress Anda.</p>','If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'Jika Anda hanya memasang plugin gratis tetapi menambahkan lisensi berbayar, silakan pasang plugin berbayar dari akun TranslatePress Anda.','Upgrade your plan to add more sites. %1$sUpgrade now%2$s'=>'Tingkatkan paket Anda untuk menambahkan lebih banyak situs. %1$sTingkatkan sekarang%2$s','You have successfully activated your license'=>'Anda telah berhasil mengaktifkan lisensi Anda','[%s] Low TranslatePress AI Words'=>'[%s] Kata TranslatePress AI Hampir Habis','upgrade your plan'=>'tingkatkan paket Anda','upgrade your plan or get extra AI Words'=>'tingkatkan paket Anda atau dapatkan kata AI tambahan','TranslatePress AI words are running low on your site.'=>'Kata TranslatePress AI di situs Anda hampir habis.','Current status: %s words remaining'=>'Status saat ini: %s kata tersisa','Once the remaining AI words run out, automatic translation through TranslatePress AI will be paused.'=>'Setelah kata AI yang tersisa habis, terjemahan otomatis melalui TranslatePress AI akan dijeda.','To continue translating your content, please %1$s over at %2$s'=>'Untuk melanjutkan penerjemahan konten Anda, silakan %1$s di %2$s','Manage Notification: %s'=>'Kelola Notifikasi: %s','Others'=>'Lainnya','Restrict by Language'=>'Batasi berdasarkan bahasa','Exclude from Language'=>'Kecualikan dari bahasa','Restrict element to language'=>'Batasi elemen ke bahasa','Show this element only in one language.'=>'Tampilkan elemen ini hanya dalam satu bahasa.','Enable translation'=>'Aktifkan terjemahan','Allow translation to the corresponding language only if the content is written in the default language.'=>'Izinkan terjemahan ke bahasa yang sesuai hanya jika konten ditulis dalam bahasa default.','Select language'=>'Pilih bahasa','Choose in which language to show this element.'=>'Pilih bahasa untuk menampilkan elemen ini.','Exclude element from language'=>'Kecualikan elemen dari bahasa','Exclude this element from specific languages.'=>'Kecualikan elemen ini dari bahasa tertentu.','Select languages'=>'Pilih bahasa','Choose from which languages to exclude this element.'=>'Pilih bahasa untuk mengecualikan elemen ini.','This element will still be visible when you are translating your website through the Translation Editor.'=>'Elemen ini akan tetap terlihat saat Anda menerjemahkan situs web melalui Editor Terjemahan.','The content of this element should be written in the default language.'=>'Konten elemen ini harus ditulis dalam bahasa default.','<strong>TranslatePress</strong> encountered SQL errors. <a href="%s" title="View TranslatePress SQL Errors">Check out the errors</a>.'=>'<strong>TranslatePress</strong> mengalami kesalahan SQL. <a href="%s" title="Lihat Kesalahan SQL TranslatePress">Periksa kesalahannya</a>.','Automatic translation has been disabled.'=>'Terjemahan otomatis telah dinonaktifkan.','Logged errors'=>'Kesalahan yang tercatat','These are the most recent 5 errors logged by TranslatePress:'=>'Berikut adalah 5 kesalahan terbaru yang dicatat oleh TranslatePress:','Yes'=>'Ya','Why are these errors occuring'=>'Mengapa kesalahan ini terjadi','If TranslatePress detects something wrong when executing queries on your database, it may disable the Automatic Translation feature in order to avoid any extra charging by Google/DeepL. Automatic Translation needs to be manually turned on, after you solve the issues.'=>'Jika TranslatePress mendeteksi ada yang salah saat menjalankan kueri pada database Anda, fitur Terjemahan Otomatis mungkin dinonaktifkan untuk menghindari biaya tambahan dari Google/DeepL. Terjemahan Otomatis perlu diaktifkan secara manual setelah Anda menyelesaikan masalahnya.','The SQL errors detected can occur for various reasons including missing tables, missing permissions for the SQL user to create tables or perform other operations, problems after site migration or changes to SQL server configuration.'=>'Kesalahan SQL yang terdeteksi dapat terjadi karena berbagai alasan, termasuk tabel yang tidak ada, kurangnya izin bagi pengguna SQL untuk membuat tabel atau melakukan operasi lain, masalah setelah migrasi situs, atau perubahan konfigurasi server SQL.','What you can do in this situation'=>'Apa yang dapat Anda lakukan dalam situasi ini','Plan A.'=>'Rencana A.','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL settings. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Buka Pengaturan -> TranslatePress -> tab Umum dan Simpan Pengaturan. Ini akan meregenerasi tabel menggunakan pengaturan SQL Anda saat ini. Periksa apakah tidak ada lagi kesalahan yang terjadi saat menjelajahi situs web Anda dalam bahasa terjemahan. Lihat stempel waktu kesalahan untuk memastikan Anda tidak melihat kesalahan lama. Hanya 5 kesalahan terbaru yang ditampilkan.','Plan B.'=>'Rencana B.','If your problem isn\'t solved, try the following steps:'=>'Jika masalah Anda belum teratasi, coba langkah-langkah berikut:','Create a backup of your database'=>'Buat cadangan database Anda','Create a copy of each translation table where you encounter errors. You can copy the table within the same database (trp_dictionary_en_us_es_es_COPY for example) -- perform this step only if you want to keep the current translations'=>'Buat salinan setiap tabel terjemahan yang mengalami kesalahan. Anda dapat menyalin tabel dalam database yang sama (misalnya trp_dictionary_en_us_es_es_COPY) -- lakukan langkah ini hanya jika Anda ingin menyimpan terjemahan saat ini.','Remove the trouble tables by executing the DROP function on them'=>'Hapus tabel yang bermasalah dengan menjalankan fungsi DROP pada tabel tersebut','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL server.'=>'Buka Pengaturan -> TranslatePress -> tab Umum dan Simpan Pengaturan. Ini akan meregenerasi tabel menggunakan server SQL Anda saat ini.','Copy the relevant content from the duplicated tables (trp_dictionary_en_us_es_es_COPY for example) in the newly generated table (trp_dictionary_en_us_es_es) -- perform this step only if you want to keep the current translations'=>'Salin konten yang relevan dari tabel yang diduplikasi (misalnya trp_dictionary_en_us_es_es_COPY) ke tabel yang baru dibuat (trp_dictionary_en_us_es_es) -- lakukan langkah ini hanya jika Anda ingin menyimpan terjemahan saat ini.','Test it to see if everything is working. If something went wrong, you can restore the backup that you\'ve made at the first step. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Uji untuk melihat apakah semuanya berfungsi. Jika terjadi masalah, Anda dapat memulihkan cadangan yang telah Anda buat di langkah pertama. Periksa apakah tidak ada lagi kesalahan yang terjadi saat menjelajahi situs web Anda dalam bahasa terjemahan. Lihat stempel waktu kesalahan untuk memastikan Anda tidak melihat kesalahan lama. Hanya 5 kesalahan terbaru yang ditampilkan.','Plan C.'=>'Rencana C.','If your problem still isn\'t solved, try asking your hosting about your errors. The most common issue is missing permissions for the SQL user, such as the Create Tables permission.'=>'Jika masalah Anda masih belum teratasi, coba tanyakan kepada penyedia hosting Anda tentang kesalahan tersebut. Masalah yang paling umum adalah kurangnya izin bagi pengguna SQL, seperti izin Create Tables.','Could not install. Try again from <a href="%s" >Plugins Dashboard.</a>'=>'Tidak dapat menginstal. Coba lagi dari <a href="%s" >Dasbor Plugin.</a>','Settings scope unknown.'=>'Cakupan pengaturan tidak diketahui.','Legacy disabled.'=>'Legacy dinonaktifkan.','Change language to %s'=>'Ubah bahasa ke %s','Automatic Translation'=>'Terjemahan Otomatis','Unsupported languages'=>'Bahasa yang tidak didukung','The selected automatic translation engine does not provide support for these languages.<br>You can still manually translate pages in these languages using the Translation Editor.'=>'Mesin terjemahan otomatis yang dipilih tidak menyediakan dukungan untuk bahasa-bahasa ini.<br>Anda masih dapat menerjemahkan halaman dalam bahasa-bahasa ini secara manual menggunakan Editor Terjemahan.','General'=>'Umum','Glossary'=>'Glosarium','API key validation failed.'=>'Validasi kunci API gagal.','API key verification was successful.'=>'Verifikasi kunci API berhasil.','Please enter your Google Translate key.'=>'Silakan masukkan kunci Google Translate Anda.','Not TranslatePress onboarding page.'=>'Bukan halaman orientasi TranslatePress.','Step %s does not exist'=>'Langkah %s tidak ada','Welcome'=>'Selamat Datang','Add Languages'=>'Tambah Bahasa','Enable Addons'=>'Aktifkan Pengaya','Finalize'=>'Selesaikan','Exit Setup'=>'Keluar dari Penyiapan','Upgrade'=>'Tingkatkan','Nothing here'=>'Tidak ada apa pun di sini','Your <strong>TranslatePress</strong> license is missing or invalid. <br/>Please %1$sregister your copy%2$s to enable automatic website translation via TranslatePress AI, premium addons, automatic updates and support. Need a license key? %3$sPurchase one now%4$s'=>'Lisensi <strong>TranslatePress</strong> Anda hilang atau tidak valid. <br/>Silakan %1$sdaftarkan salinan Anda%2$s untuk mengaktifkan terjemahan situs web otomatis via TranslatePress AI, addon premium, pembaruan otomatis, dan dukungan. Butuh kunci lisensi? %3$sBeli sekarang%4$s','Your license is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Lisensi Anda dinonaktifkan untuk URL ini. Aktifkan kembali dari <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Kelola Situs.','You have reached the activation limit for your <strong>%1$s</strong> license. <br/>Manage your active sites from %2$s your account %3$s.'=>'Anda telah mencapai batas aktivasi untuk lisensi <strong>%1$s</strong> Anda. <br/>Kelola situs aktif Anda dari %2$s akun Anda %3$s.','License key mismatch. The license you entered doesn’t match the <strong>%1$s</strong> version you have installed. <br/>Please check that you’ve installed the correct version for your license from your %2$sTranslatePress account%3$s.'=>'Kunci lisensi tidak cocok. Lisensi yang Anda masukkan tidak cocok dengan versi <strong>%1$s</strong> yang telah Anda instal. <br/>Silakan periksa bahwa Anda telah menginstal versi yang benar untuk lisensi Anda dari %2$sakun TranslatePress%3$s Anda.','<br/>If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'<br/>Jika Anda hanya menginstal plugin gratis tetapi menambahkan lisensi berbayar, silakan instal plugin berbayar dari akun TranslatePress Anda.','Your <strong>TranslatePress</strong> license has expired. <br/>Please %1$sRenew Your Licence%2$s to continue receiving access to automatic translations via TranslatePress AI, premium addons, product downloads, and automatic updates. %3$sRenew now %4$s'=>'Lisensi <strong>TranslatePress</strong> Anda telah berakhir. <br/>Silakan %1$sPerpanjang Lisensi Anda%2$s untuk terus mendapatkan akses ke terjemahan otomatis via TranslatePress AI, addon premium, unduhan produk, dan pembaruan otomatis. %3$sPerpanjang sekarang %4$s','Error: '=>'Kesalahan: ','Something went wrong, please try again.'=>'Terjadi kesalahan, silakan coba lagi.','Your <strong>TranslatePress</strong> license will expire on %1$s. Please %2$sRenew Your Licence%3$s to continue receiving access to automatic translations via TP AI, premium addons, product downloads and automatic updates. %4$sRenew Now%5$s'=>'Lisensi <strong>TranslatePress</strong> Anda akan berakhir pada %1$s. Silakan %2$sPerpanjang Lisensi Anda%3$s untuk terus mendapatkan akses ke terjemahan otomatis via TP AI, addon premium, unduhan produk, dan pembaruan otomatis. %4$sPerpanjang Sekarang%5$s','Please %1$senter%2$s your license key to enable %3$s automatic translation.'=>'Silakan %1$smasukkan%2$s kunci lisensi Anda untuk mengaktifkan terjemahan otomatis %3$s.','%1$s automatic translation requires an active license. Please %2$srenew%3$s your license or purchase a new one %4$shere%5$s.'=>'Terjemahan otomatis %1$s memerlukan lisensi aktif. Silakan %2$sperpanjang%3$s lisensi Anda atau beli yang baru %4$sdi sini%5$s.','You have less than 5,000 TranslatePress AI words remaining. To continue automatically translating your website, please %spurchase additional AI words at a discount from your account%s.'=>'Sisa kata TranslatePress AI Anda kurang dari 5.000. Untuk terus menerjemahkan situs web Anda secara otomatis, silakan %sbeli kata AI tambahan dengan diskon dari akun Anda%s.','You do not have a valid license for <strong>TranslatePress</strong>. %1$sGet one for free%2$s to get access to TranslatePress AI.'=>'Anda tidak memiliki lisensi yang valid untuk <strong>TranslatePress</strong>. %1$sDapatkan secara gratis%2$s untuk mendapatkan akses ke TranslatePress AI.',' Error: '=>' Kesalahan: ','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Learn more</a>.'=>'<strong>BARU:</strong> Add-on <strong>Different Domain per Language</strong> telah hadir! Tingkatkan SEO global Anda dan ciptakan pengalaman lokal dengan domain khusus negara seperti .de atau .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Pelajari selengkapnya</a>.','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. Upgrade to <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business or Developer</a> to access it + more premium perks!'=>'<strong>BARU:</strong> Add-on <strong>Different Domain per Language</strong> telah hadir! Tingkatkan SEO global Anda dan ciptakan pengalaman lokal dengan domain khusus negara seperti .de atau .fr. Tingkatkan ke <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business atau Developer</a> untuk mengaksesnya + lebih banyak keuntungan premium!','The daily quota for machine translation characters exceeded. Please check the <strong>TranslatePress -> <a href="%s">Automatic Translation</a></strong> page for more information.'=>'Kuota harian untuk karakter terjemahan mesin telah terlampaui. Silakan periksa halaman <strong>TranslatePress -> <a href="%s">Terjemahan Otomatis</a></strong> untuk informasi lebih lanjut.','Marketing optin'=>'Opt-in Pemasaran','Opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Setuju untuk menerima pemberitahuan pembaruan keamanan dan fitur, serta pelacakan diagnostik yang tidak sensitif.','TranslatePress Preferred User Language'=>'Bahasa Pilihan Pengguna TranslatePress','Preferred language to navigate the site'=>'Bahasa pilihan untuk menjelajahi situs','The language is automatically set based by the last visited language by the user.'=>'Bahasa diatur secara otomatis berdasarkan bahasa terakhir yang dikunjungi pengguna.','Always use this language'=>'Selalu gunakan bahasa ini','By checking this setting the preferred language will remain the one selected above, without the possibility of being changed in the frontend.<br>This language will be used in different operations such as sending email to the user.'=>'Dengan mencentang pengaturan ini, bahasa pilihan akan tetap menjadi yang dipilih di atas dan tidak dapat diubah di frontend.<br>Bahasa ini akan digunakan dalam berbagai operasi seperti mengirim email kepada pengguna.','Hello! Seems like you\'ve been using <strong>TranslatePress</strong> for a while now to translate your website. That\'s awesome! '=>'Halo! Sepertinya Anda telah menggunakan <strong>TranslatePress</strong> untuk menerjemahkan situs web Anda sudah beberapa waktu. Itu luar biasa! ','If you can spare a few moments to rate it on WordPress.org it would help us a lot (and boost my motivation).'=>'Jika Anda dapat meluangkan waktu sejenak untuk menilainya di WordPress.org, akan sangat membantu kami (dan meningkatkan motivasi saya).','~ Razvan, developer of TranslatePress'=>'~ Razvan, pengembang TranslatePress','Rate TranslatePress on WordPress.org plugin page'=>'Nilai TranslatePress di halaman plugin WordPress.org','Ok, I will gladly help!'=>'Oke, saya akan dengan senang hati membantu!','No, thanks.'=>'Tidak, terima kasih.','Full Language Names'=>'Nama Bahasa Lengkap','Short Language Names'=>'Nama Bahasa Singkat','Flags with Full Language Names'=>'Bendera dengan Nama Bahasa Lengkap','Flags with Short Language Names'=>'Bendera dengan Nama Bahasa Singkat','Only Flags'=>'Hanya Bendera','Full Language Names No HTML'=>'Nama Bahasa Lengkap Tanpa HTML','Bottom Right'=>'Kanan Bawah','Bottom Left'=>'Kiri Bawah','Top Right'=>'Kanan Atas','Top Left'=>'Kiri Atas','Dark'=>'Gelap','Light'=>'Terang','Install & Activate'=>'Instal & Aktifkan','Invalid language code. Please try again.'=>'Kode bahasa tidak valid. Silakan coba lagi.','Language codes can contain only A-Z a-z 0-9 - _ characters. Check your language codes in TranslatePress General Settings.'=>'Kode bahasa hanya boleh berisi karakter A-Z a-z 0-9 - _. Periksa kode bahasa Anda di Pengaturan Umum TranslatePress.','Error! Duplicate URL slug values.'=>'Kesalahan! Nilai slug URL duplikat.','You cannot select two languages that have the same <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">iso code</a> but different formalities because doing so will lead to duplicate <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">hreflang tags</a>.'=>'Anda tidak dapat memilih dua bahasa yang memiliki <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">kode ISO</a> yang sama tetapi formalitas berbeda karena hal tersebut akan menyebabkan <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">tag hreflang</a> duplikat.','Duplicate language detected.<br>Each language can only be added once to ensure accurate translation management.<br> Please change the duplicate language entry and try again. '=>'Bahasa duplikat terdeteksi.<br>Setiap bahasa hanya dapat ditambahkan satu kali untuk memastikan manajemen terjemahan yang akurat.<br> Silakan ubah entri bahasa yang duplikat dan coba lagi. ','Current Language'=>'Bahasa Saat Ini','Opposite Language'=>'Bahasa Berlawanan','Addons'=>'Pengaya','Settings'=>'Pengaturan','Pro Features'=>'Fitur Pro','Activate License'=>'Aktifkan Lisensi','Need Help?'=>'Butuh Bantuan?','Recent community discussions'=>'Diskusi komunitas terbaru','Loading...'=>'Memuat...','Unable to load forum posts'=>'Tidak dapat memuat pos forum','Ask a Question'=>'Ajukan Pertanyaan','View All Topics'=>'Lihat Semua Topik','by'=>'oleh','Have a question?'=>'Punya pertanyaan?','Get help directly from the plugin developers, suggest improvements, or share your feedback!'=>'Dapatkan bantuan langsung dari pengembang plugin, sarankan perbaikan, atau bagikan masukan Anda!','Tip for faster help:'=>'Tips untuk bantuan lebih cepat:','Include what you tried, what you expected, and what happened. Screenshots help!'=>'Sertakan apa yang Anda coba, apa yang Anda harapkan, dan apa yang terjadi. Tangkapan layar membantu!','Toggle support chat'=>'Alihkan obrolan dukungan','Ask the community'=>'Tanyakan ke komunitas','Close'=>'Tutup','Empty feed response'=>'Respons feed kosong','Unable to parse feed'=>'Tidak dapat mengurai feed','Just now'=>'Baru saja','%d hour ago'=>'%d jam yang lalu','%d day ago'=>'%d hari yang lalu','Source'=>'Sumber','Srcset'=>'Srcset','Alt attribute'=>'Atribut alt','Title attribute'=>'Atribut title','Anchor link'=>'Tautan jangkar','Placeholder attribute'=>'Atribut placeholder','Submit attribute'=>'Atribut submit','Text'=>'Teks','Video Poster'=>'Poster video','plural form'=>'bentuk jamak','one'=>'satu','few'=>'beberapa','many'=>'banyak','other'=>'lainnya','Saved'=>'Tersimpan','Save'=>'Simpan','Saving translation...'=>'Menyimpan terjemahan...','You have unsaved changes!'=>'Anda memiliki perubahan yang belum disimpan!','Discard changes'=>'Buang perubahan','Discard All'=>'Buang Semua','Loading Strings...'=>'Memuat String...','Select string to translate...'=>'Pilih string untuk diterjemahkan...','Close Editor'=>'Tutup Editor','From'=>'Dari','To'=>'Ke','Add Media'=>'Tambah Media','Other languages'=>'Bahasa lain','Context'=>'Konteks','View Website As'=>'Lihat Situs Sebagai','Available in our Pro Versions'=>'Tersedia di versi Pro kami','Select or Upload Media'=>'Pilih atau Unggah Media','Use this media'=>'Gunakan media ini','Translate'=>'Terjemahkan','Translate entire block element'=>'Terjemahkan seluruh elemen blok','Split block to translate strings individually'=>'Pisahkan blok untuk menerjemahkan string satu per satu','Save changes to translation. Shortcut: CTRL(⌘) + S'=>'Simpan perubahan terjemahan. Pintasan: CTRL(⌘) + S','Navigate to next string in dropdown list. Shortcut: CTRL(⌘) + ALT + Right Arrow'=>'Pindah ke string berikutnya di daftar dropdown. Pintasan: CTRL(⌘) + ALT + Panah Kanan','Navigate to previous string in dropdown list. Shortcut: CTRL(⌘) + ALT + Left Arrow'=>'Pindah ke string sebelumnya di daftar dropdown. Pintasan: CTRL(⌘) + ALT + Panah Kiri','Discard all changes. Shortcut: CTRL(⌘) + ALT + Z'=>'Buang semua perubahan. Pintasan: CTRL(⌘) + ALT + Z','Discard changes to this text box. To discard changes to all text boxes use shortcut: CTRL(⌘) + ALT + Z'=>'Buang perubahan pada kotak teks ini. Untuk membuang perubahan pada semua kotak teks gunakan pintasan: CTRL(⌘) + ALT + Z','Dismiss tooltip'=>'Tutup tooltip','Quick Intro'=>'Pengenalan Singkat','Are you sure you want to split this phrase into smaller parts?'=>'Apakah Anda yakin ingin memecah frasa ini menjadi bagian-bagian yang lebih kecil?','This string is not ready for translation yet. <br>Try again in a moment...'=>'String ini belum siap untuk diterjemahkan. <br>Coba lagi sebentar...','For this option to work, please update the Browse as other role add-on to the latest version.'=>'Agar opsi ini berfungsi, harap perbarui add-on Browse as other role ke versi terbaru.','To translate slugs, please update the SEO Pack add-on to the latest version.'=>'Untuk menerjemahkan slug, harap perbarui add-on SEO Pack ke versi terbaru.','You can add a new language from <a href="%s">Settings->TranslatePress</a>'=>'Anda dapat menambahkan bahasa baru dari <a href="%s">Pengaturan->TranslatePress</a>','However, you can still use TranslatePress to <strong style="background: #f5fb9d;">modify gettext strings</strong> available in your page.'=>'Namun, Anda masih dapat menggunakan TranslatePress untuk <strong style="background: #f5fb9d;">memodifikasi string gettext</strong> yang tersedia di halaman Anda.','Strings that are user-created cannot be modified, only those from themes and plugins.'=>'String yang dibuat pengguna tidak dapat dimodifikasi, hanya yang dari tema dan plugin.','Extra Translation Features'=>'Fitur Terjemahan Ekstra','Support for 130+ Extra Languages'=>'Dukungan untuk 130+ Bahasa Ekstra','Access to TranslatePress AI'=>'Akses ke TranslatePress AI','Translate SEO Title, Description, Slug'=>'Terjemahkan Judul SEO, Deskripsi, Slug','Publish only when translation is complete'=>'Terbitkan hanya jika terjemahan sudah selesai','Translate by Browsing as User Role'=>'Terjemahkan dengan Menelusuri sebagai Peran Pengguna','Different Menu Items for each Language'=>'Item Menu Berbeda untuk Setiap Bahasa','Upgrade to PRO'=>'Tingkatkan ke PRO','Upgrade to PRO with our biggest discount of the year!'=>'Tingkatkan ke PRO dengan diskon terbesar kami tahun ini!','This Black Friday, get access to these features and more at a fraction of the costs:'=>'Pada Black Friday ini, dapatkan akses ke fitur-fitur ini dan lainnya dengan harga yang jauh lebih murah:','No available suggestions'=>'Tidak ada saran yang tersedia','Suggestions from translation memory'=>'Saran dari memori terjemahan','Click to Copy'=>'Klik untuk Menyalin','Human Translation'=>'Terjemahan Manusia','Machine Translation'=>'Terjemahan Mesin','Gettext File Translation'=>'Terjemahan File Gettext','Text on this page is %s% translated into all languages.'=>'Teks di halaman ini telah diterjemahkan %s% ke semua bahasa.','%1$s% of text on this page is translated into %2$s.'=>'%1$s% teks di halaman ini telah diterjemahkan ke %2$s.','This page is %1$s% translated into %2$s.'=>'Halaman ini telah diterjemahkan %1$s% ke %2$s.','The slug that you are trying to edit is present in other slug types:%s%. Editing it will replace each occurrence, regardless of the current type.'=>'Slug yang Anda coba edit terdapat di jenis slug lain: %s. Mengeditnya akan mengganti setiap kemunculan, terlepas dari jenis saat ini.','Hover any text on the page, click %s,<br> then modify the translation in the sidebar.'=>'Arahkan kursor ke teks apa pun di halaman, klik %s,<br> lalu ubah terjemahan di bilah samping.','Don\'t forget to Save Translation. Use keyboard shortcut CTRL(⌘) + S'=>'Jangan lupa Simpan Terjemahan. Gunakan pintasan keyboard CTRL(⌘) + S','Switch language to see the translation changes directly on the page.'=>'Ubah bahasa untuk melihat perubahan terjemahan langsung di halaman.','Search for any text in this page in the dropdown.'=>'Cari teks apa pun di halaman ini di dropdown.','Your %s license has <span class="trp-license-status-emphasized">expired</span>.'=>'Lisensi %s Anda telah <span class="trp-license-status-emphasized">kadaluwarsa</span>.','<strong>This Black Friday, renew your license at a special price</strong> to continue receiving access to product downloads, automatic updates, and support.'=>'<strong>Black Friday kali ini, perbarui lisensi Anda dengan harga spesial</strong> untuk terus mendapatkan akses ke unduhan produk, pembaruan otomatis, dan dukungan.','Get Deal'=>'Dapatkan Penawaran','Please renew your license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Harap perbarui lisensi Anda untuk terus mendapatkan akses ke TranslatePress AI, addon premium, pembaruan otomatis, dan dukungan.','Renew Now'=>'Perbarui Sekarang','Your %s license was <span class="trp-license-status-emphasized">refunded</span>.'=>'Lisensi %s Anda telah <span class="trp-license-status-emphasized">dikembalikan dananya</span>.','Please purchase a new license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Harap beli lisensi baru untuk terus mendapatkan akses ke TranslatePress AI, addon premium, pembaruan otomatis, dan dukungan.','Purchase a new license'=>'Beli lisensi baru','Your %s license is <span class="trp-license-status-emphasized">missing or invalid</span>.'=>'Lisensi %s Anda <span class="trp-license-status-emphasized">hilang atau tidak valid</span>.','Please enter a valid license to get access to TranslatePress AI, premium addons, automatic updates and support. Need a license key? %1$sPurchase one now%2$s'=>'Silakan masukkan lisensi yang valid untuk mendapatkan akses ke TranslatePress AI, add-on premium, pembaruan otomatis, dan dukungan. Butuh kunci lisensi? %1$sBeli sekarang%2$s','Enter a valid license'=>'Masukkan lisensi yang valid','Meta Information'=>'Informasi Meta','String List'=>'Daftar String','Gettext Strings'=>'String Gettext','Images'=>'Gambar','Videos'=>'Video','Audios'=>'Audio','Dynamically Added Strings'=>'String yang Ditambahkan Secara Dinamis','Translation Editor'=>'Editor Terjemahan','Edit translations by visually selecting them on each site page'=>'Sunting terjemahan dengan memilihnya secara visual di setiap halaman situs','String Translation'=>'Terjemahan String','Edit url slug translations, plugins and theme translation (emails, forms etc.)'=>'Edit terjemahan slug URL, plugin, dan tema (email, formulir, dll.)','Current User'=>'Pengguna Saat Ini','Logged Out'=>'Tidak Masuk','Translate Page'=>'Terjemahkan Halaman','Add a New Language'=>'Tambah Bahasa Baru','Your License is Invalid'=>'Lisensi Anda Tidak Valid','Get More AI Words (%d left)'=>'Dapatkan Lebih Banyak Kata AI (%d tersisa)','Opens post in the translation editor. Post must be saved as draft or published beforehand.'=>'Membuka pos di editor terjemahan. Pos harus disimpan sebagai draf atau diterbitkan terlebih dahulu.','Security check'=>'Pemeriksaan keamanan','<strong>Warning:</strong> Some strings have possibly incorrectly encoded characters. This may result in breaking the queries, rendering the page untranslated in live mode. Consider revising the following strings or their method of outputting.'=>'<strong>Peringatan:</strong> Beberapa string memiliki karakter yang mungkin dienkode secara tidak benar. Hal ini dapat mengakibatkan rusaknya query, sehingga halaman tidak diterjemahkan dalam mode live. Pertimbangkan untuk meninjau ulang string berikut atau metode outputnya.','IMPORTANT: It is strongly recommended to first backup the database!'=>'PENTING: Sangat disarankan untuk mencadangkan database terlebih dahulu!','Are you sure you want to continue?'=>'Apakah Anda yakin ingin melanjutkan?','TranslatePress data update'=>'Pembaruan data TranslatePress','We need to update your translations database to the latest version.'=>'Kami perlu memperbarui basis data terjemahan Anda ke versi terbaru.','Updating will allow editing translations of localized text from plugins and theme. Existing translation will still work as expected.'=>'Pembaruan akan memungkinkan pengeditan terjemahan teks yang dilokalkan dari plugin dan tema. Terjemahan yang ada akan tetap berfungsi seperti yang diharapkan.','Run the updater'=>'Jalankan pembaruan','Updating will allow editing translations of slugs. Existing translation will still work as expected.'=>'Pembaruan akan memungkinkan pengeditan terjemahan slug. Terjemahan yang ada akan tetap berfungsi sebagaimana mestinya.','Please activate the SEO Addon from <br/>WordPress -> Settings -> TranslatePress -> Addons section'=>'Silakan aktifkan Pengaya SEO dari <br/>WordPress -> Pengaturan -> TranslatePress -> bagian Pengaya','Go to Addons'=>'Buka Pengaya','The SEO Pack add-on allows translation of all the URL slugs:'=>'Pengaya SEO Pack memungkinkan penerjemahan semua slug URL:','Taxonomy slugs'=>'Slug taksonomi','Term slugs'=>'Slug istilah','Post slugs (this includes pages and custom post types)'=>'Slug pos (ini mencakup halaman dan jenis pos kustom)','Post type base slugs'=>'Slug dasar jenis pos','WooCommerce slugs'=>'Slug WooCommerce','The SEO Pack add-on is available with ALL premium versions of the plugin.'=>'Add-on SEO Pack tersedia untuk SEMUA versi premium plugin.','Upgrade to Pro'=>'Tingkatkan ke Pro','Description'=>'Deskripsi','Article Section'=>'Bagian Artikel','Article Tag'=>'Tag Artikel','OG Title'=>'Judul OG','OG Site Name'=>'Nama Situs OG','OG Description'=>'Deskripsi OG','OG Image Alt'=>'Alt Gambar OG','Twitter Title'=>'Judul Twitter','Twitter Description'=>'Deskripsi Twitter','Twitter Image Alt'=>'Alt Gambar Twitter','Page Title'=>'Judul Halaman','Dublin Core Title'=>'Judul Dublin Core','Dublin Core Description'=>'Deskripsi Dublin Core','OG Image'=>'Gambar OG','OG Image Secure URL'=>'URL Aman Gambar OG','Twitter Image'=>'Gambar Twitter','Removing cdata dictionary strings for language %s...'=>'Menghapus string kamus cdata untuk bahasa %s...','Removing untranslated dictionary links for language %s...'=>'Menghapus tautan kamus yang belum diterjemahkan untuk bahasa %s...','Removing duplicated gettext strings for language %s...'=>'Menghapus string gettext yang diduplikasi untuk bahasa %s...','Removing duplicated dictionary strings for language %s...'=>'Menghapus string kamus yang diduplikasi untuk bahasa %s...','Removing untranslated dictionary strings where translation is available for language %s...'=>'Menghapus string kamus yang belum diterjemahkan yang memiliki terjemahan tersedia untuk bahasa %s...','Inserting original strings for language %s...'=>'Memasukkan string asli untuk bahasa %s...','Cleaning original strings table for language %s...'=>'Membersihkan tabel string asli untuk bahasa %s...','Updating original string ids for language %s...'=>'Memperbarui ID string asli untuk bahasa %s...','Regenerating original meta table for language %s...'=>'Menghasilkan ulang tabel meta asli untuk bahasa %s...','Cleaning original meta table for language %s...'=>'Membersihkan tabel meta asli untuk bahasa %s...','Replacing original id NULL with value for language %s...'=>'Mengganti ID asli NULL dengan nilai untuk bahasa %s...','Inserting gettext original strings for language %s...'=>'Memasukkan string asli gettext untuk bahasa %s...','Cleaning gettext original strings table for language %s...'=>'Membersihkan tabel string asli gettext untuk bahasa %s...','Updating gettext original string ids for language %s...'=>'Memperbarui ID string asli gettext untuk bahasa %s...','Starting gettext database optimization in the background...'=>'Memulai pengoptimalan database gettext di latar belakang...','Migrating taxonomy and post type base slugs to new table structure...'=>'Memigrasi slug taksonomi dan slug dasar jenis pos ke struktur tabel baru...','Migrating post slugs to new table structure for language %s...'=>'Memigrasi slug pos ke struktur tabel baru untuk bahasa %s...','Migrating term slugs to new table structure for language %s...'=>'Memigrasi slug istilah ke struktur tabel baru untuk bahasa %s...','Finishing up...'=>'Menyelesaikan...','TranslatePress needs to optimize gettext database tables. Translations continue to work while this runs in the background.'=>'TranslatePress perlu mengoptimalkan tabel database gettext. Terjemahan akan terus berfungsi selama proses ini berjalan di latar belakang.','Before starting, we strongly recommend creating a database backup.'=>'Sebelum memulai, kami sangat menyarankan untuk membuat cadangan database.','Start optimization'=>'Mulai optimasi','Update aborted! Could not schedule gettext database optimization.'=>'Pembaruan dibatalkan! Tidak dapat menjadwalkan optimasi basis data gettext.','Database optimization did not complete successfully. We recommend restoring the original database or <a href="%s" >trying again.</a>'=>'Optimasi database tidak berhasil diselesaikan. Kami menyarankan untuk memulihkan database asli atau <a href="%s" >mencoba lagi.</a>','Update aborted! Your user account doesn\'t have the capability to perform database updates.'=>'Pembaruan dibatalkan! Akun pengguna Anda tidak memiliki kemampuan untuk melakukan pembaruan database.','Update aborted! Invalid nonce.'=>'Pembaruan dibatalkan! Nonce tidak valid.','Back to TranslatePress Settings'=>'Kembali ke Pengaturan TranslatePress','Successfully updated database!'=>'Database berhasil diperbarui!','Updating database to version %s+'=>'Memperbarui database ke versi %s+','Processing table for language %s...'=>'Memproses tabel untuk bahasa %s...','Update aborted! Incorrect action.'=>'Pembaruan dibatalkan! Tindakan tidak benar.','Update aborted! Start the gettext database optimization separately from the Advanced settings page.'=>'Pembaruan dibatalkan! Mulai optimasi basis data gettext secara terpisah dari halaman pengaturan lanjutan.','Update aborted! Incorrect language code.'=>'Pembaruan dibatalkan! Kode bahasa salah.',' done.'=>' selesai.','Update aborted while %1$s. SQL error: %2$s'=>'Pembaruan dibatalkan saat %1$s. Kesalahan SQL: %2$s','inserting original strings'=>'menyisipkan string asli','checking original string insertion progress'=>'memeriksa kemajuan penyisipan string asli','cleaning duplicate original strings'=>'membersihkan string asli yang duplikat','updating original string IDs'=>'memperbarui ID string asli','checking original string ID update progress'=>'memeriksa kemajuan pembaruan ID string asli','inserting gettext original strings'=>'menyisipkan string asli gettext','checking gettext original insertion progress'=>'memeriksa kemajuan penyisipan string asli gettext','cleaning duplicate gettext original strings'=>'membersihkan string asli gettext yang duplikat','updating gettext original string IDs'=>'memperbarui ID string asli gettext','checking gettext original string ID update progress'=>'memeriksa kemajuan pembaruan ID string asli gettext','All individual TranslatePress add-on plugins <a href="%1$s" target="_blank">have been discontinued</a> and are now included in the premium Personal, Business and Developer versions of TranslatePress. Please log into your <a href="%2$s" target="_blank">account page</a>, download the new premium version and install it. Your individual addons settings will be ported over.'=>'Semua plugin add-on TranslatePress individual <a href="%1$s" target="_blank">telah dihentikan</a> dan kini disertakan dalam versi premium Personal, Business, dan Developer TranslatePress. Silakan masuk ke <a href="%2$s" target="_blank">halaman akun</a> Anda, unduh versi premium baru, dan instal. Pengaturan add-on individual Anda akan dipindahkan.','Brand-new Language Switcher Settings are here!'=>'Pengaturan Pengalih Bahasa yang sepenuhnya baru telah hadir!','Explore pre-made templates, switch colors, flag styles, spacing, layouts & more. Use the live preview to perfect your switcher in seconds.'=>'Jelajahi templat bawaan, ubah warna, gaya bendera, spasi, tata letak, dan lainnya. Gunakan pratinjau langsung untuk menyempurnakan pengalih bahasa Anda dalam hitungan detik.','Start customizing'=>'Mulai menyesuaikan','Read documentation'=>'Baca dokumentasi','<strong>TranslatePress</strong> requires <strong><a href="http://php.net/manual/en/book.mbstring.php">Multibyte String PHP library</a></strong>. Please contact your server administrator to install it on your server.'=>'<strong>TranslatePress</strong> memerlukan <strong><a href="http://php.net/manual/en/book.mbstring.php">Pustaka Multibyte String PHP</a></strong>. Silakan hubungi administrator server Anda untuk menginstalnya di server Anda.','Detected long query limitation on WPEngine hosting. Some large pages may appear untranslated. You can remove limitation by adding the following to your site’s wp-config.php: define( \'WPE_GOVERNOR\', false ); '=>'Terdeteksi pembatasan kueri panjang pada hosting WPEngine. Beberapa halaman besar mungkin muncul tidak diterjemahkan. Anda dapat menghapus pembatasan dengan menambahkan berikut ini ke wp-config.php situs Anda: define( \'WPE_GOVERNOR\', false ); ','Custom Language Flag'=>'Bendera Bahasa Kustom','The Language code of the added custom language is invalid.'=>'Kode bahasa dari bahasa kustom yang ditambahkan tidak valid.','The Language code of the added custom language cannot be empty.'=>'Kode bahasa dari bahasa kustom yang ditambahkan tidak boleh kosong.','The Automatic Translation Code of the added custom language is invalid.'=>'Kode Terjemahan Otomatis dari bahasa kustom yang ditambahkan tidak valid.','Style'=>'Gaya','Use shortcode settings'=>'Gunakan pengaturan shortcode','Custom'=>'Kustom','Language names'=>'Nama bahasa','Full names'=>'Nama lengkap','Short names'=>'Nama singkat','Hide names'=>'Sembunyikan nama','Flag position'=>'Posisi bendera','Before text'=>'Sebelum teks','After text'=>'Setelah teks','Hide flags'=>'Sembunyikan bendera','Open on click'=>'Buka saat diklik','Show opposite language'=>'Tampilkan bahasa berlawanan','Size'=>'Ukuran','Normal'=>'Normal','Large'=>'Besar','Flag shape'=>'Bentuk bendera','Rectangle'=>'Persegi panjang','Square'=>'Persegi','Rounded'=>'Membulat','Transitions'=>'Transisi','Background'=>'Latar belakang','Hover background'=>'Latar belakang hover','Hover text'=>'Teks hover','Border color'=>'Warna tepi','Border width'=>'Lebar tepi','Border radius'=>'Radius tepi','Flag radius'=>'Radius bendera','Disable the legacy TranslatePress language switcher to use the customizable Elementor widget. <a href="%s" target="_blank" rel="noopener noreferrer">Open language switcher settings</a>.'=>'Nonaktifkan pengalih bahasa TranslatePress versi lama untuk menggunakan widget Elementor yang dapat disesuaikan. <a href="%s" target="_blank" rel="noopener noreferrer">Buka pengaturan pengalih bahasa</a>.','The language switcher inherits styling options from shortcode. <a href="%s" target="_blank" rel="noopener noreferrer">Open shortcode settings</a>.'=>'Pengalih bahasa mewarisi pilihan gaya dari shortcode. <a href="%s" target="_blank" rel="noopener noreferrer">Buka pengaturan shortcode</a>.','TranslatePress AI'=>'TranslatePress AI','Your TranslatePress AI API Key is valid.'=>'Kunci API TranslatePress AI Anda valid.','Your TranslatePress AI API Key is invalid.'=>'Kunci API TranslatePress AI Anda tidak valid.','Your TranslatePress AI API Key has expired.'=>'Kunci API TranslatePress AI Anda telah kedaluwarsa.','Activate API Key'=>'Aktifkan Kunci API','Deactivate API Key'=>'Nonaktifkan Kunci API','Add a TranslatePress AI API Key'=>'Tambahkan Kunci API TranslatePress AI','TranslatePress AI API Key'=>'Kunci API TranslatePress AI','Manage your TranslatePress AI API Key in your %1$s.'=>'Kelola Kunci API TranslatePress AI Anda di %1$s Anda.','Don’t have a TranslatePress AI API Key?'=>'Belum memiliki Kunci API TranslatePress AI?','Get a free TranslatePress AI API Key Today'=>'Dapatkan Kunci API TranslatePress AI gratis hari ini','Add your TranslatePress AI API Key'=>'Tambahkan Kunci API TranslatePress AI Anda','Add your TranslatePress AI API Key to unlock all premium features. Find the TranslatePress AI API Key in your'=>'Tambahkan Kunci API TranslatePress AI Anda untuk membuka semua fitur premium. Temukan Kunci API TranslatePress AI Anda di','Your TranslatePress AI API Key is valid and active.'=>'Kunci API TranslatePress AI Anda valid dan aktif.','Activate TranslatePress AI API Key'=>'Aktifkan Kunci API TranslatePress AI','No Active API Key Detected for this website.'=>'Tidak ada kunci API aktif yang terdeteksi untuk situs web ini.','In order to enable Automatic Translation using TranslatePress AI, you need an API key by creating a free account.'=>'Untuk mengaktifkan Terjemahan Otomatis menggunakan TranslatePress AI, Anda memerlukan kunci API dengan membuat akun gratis.','Enter your API key'=>'Masukkan kunci API Anda','In order to enable Automatic Translation using TranslatePress AI, please enter your API key from'=>'Untuk mengaktifkan Terjemahan Otomatis menggunakan TranslatePress AI, silakan masukkan kunci API Anda dari','API Key'=>'Kunci API','No Active TranslatePress AI API Key Detected for this website.'=>'Tidak ada kunci API TranslatePress AI yang aktif terdeteksi untuk situs web ini.','Get Your Free TranslatePress AI API Key'=>'Dapatkan kunci API TranslatePress AI gratis Anda','Generate API Key'=>'Hasilkan kunci API','You have a valid %s <strong>API Key</strong>.'=>'Anda memiliki <strong>kunci API</strong> %s yang valid.','Manage your API Key & quota on the %s'=>'Kelola kunci API dan kuota Anda di %s','Get a Free AI API Key'=>'Dapatkan kunci API AI gratis','This website is already activated under a free API key. Each website can only use one free API key.'=>'Situs web ini sudah diaktifkan dengan kunci API gratis. Setiap situs web hanya dapat menggunakan satu kunci API gratis.','This website is already activated under a free API key. Each website can only use one free API key. Please upgrade to a premium plan for more TranslatePress AI words from %1$s your account %2$s.'=>'Situs web ini sudah diaktifkan dengan kunci API gratis. Setiap situs web hanya dapat menggunakan satu kunci API gratis. Silakan tingkatkan ke paket premium untuk mendapatkan lebih banyak kata TranslatePress AI dari %1$sakun Anda%2$s.','Debug Data for API Key Checking'=>'Data debug untuk pemeriksaan kunci API','Debug Data for API Key Activation'=>'Data debug untuk aktivasi kunci API','TranslatePress finished replacing the existing translations in your dictionary.'=>'TranslatePress selesai mengganti terjemahan yang ada di kamus Anda.','Term (%s)'=>'Istilah (%s)','Translations'=>'Terjemahan','Term added. Glossary terms only affect new automatic translations.'=>'Istilah ditambahkan. Istilah glosarium hanya memengaruhi terjemahan otomatis baru.','Term updated.'=>'Istilah diperbarui.','Term deleted.'=>'Istilah dihapus.','Are you sure you want to delete this term?'=>'Apakah Anda yakin ingin menghapus istilah ini?','Something went wrong. Please try again.'=>'Terjadi kesalahan. Silakan coba lagi.','Quick Edit'=>'Edit Cepat','Edit'=>'Sunting','Delete'=>'Hapus','Update'=>'Perbarui','Cancel'=>'Batal','No glossary terms match your search.'=>'Tidak ada istilah glosarium yang cocok dengan pencarian Anda.','No glossary terms found.'=>'Tidak ada istilah glosarium yang ditemukan.','Could not load glossary terms. Please reload the page.'=>'Gagal memuat istilah glosarium. Silakan muat ulang halaman.','items'=>'item','of'=>'dari','First page'=>'Halaman pertama','Previous page'=>'Halaman sebelumnya','Next page'=>'Halaman berikutnya','Last page'=>'Halaman terakhir','The inserted term was found in your existing translations, use the %s to make changes there.'=>'Istilah yang dimasukkan ditemukan dalam terjemahan Anda yang sudah ada, gunakan %s untuk membuat perubahan di sana.','search & replace tool'=>'alat pencarian dan penggantian','Please provide at least one existing translation to replace.'=>'Harap sediakan setidaknya satu terjemahan yang sudah ada untuk diganti.','You are about to bulk edit a potentially large amount of translations. This action cannot be undone. It is recommended to make a backup of the database before completing this action.'=>'Anda akan menyunting sejumlah besar terjemahan secara massal. Tindakan ini tidak dapat dibatalkan. Disarankan untuk membuat cadangan basis data sebelum menyelesaikan tindakan ini.','Continue with replacing existing translations?'=>'Lanjutkan mengganti terjemahan yang sudah ada?','No entries found.'=>'Tidak ada entri yang ditemukan.','Original'=>'Asli','Security check failed. Please reload the page and try again.'=>'Pemeriksaan keamanan gagal. Silakan muat ulang halaman dan coba lagi.','You do not have permission to do this.'=>'Anda tidak memiliki izin untuk melakukan ini.','Please enter the term in the default language.'=>'Harap masukkan istilah dalam bahasa default.','Please provide at least one translation for the term.'=>'Harap sediakan setidaknya satu terjemahan untuk istilah tersebut.','The term “%s” already exists in the glossary.'=>'Istilah “%s” sudah ada dalam glosarium.','The term you are trying to edit no longer exists. Please reload the page.'=>'Istilah yang Anda coba sunting tidak lagi ada. Harap muat ulang halaman.','The term you are trying to delete no longer exists. Please reload the page.'=>'Istilah yang Anda coba hapus tidak lagi ada. Harap muat ulang halaman.','%1$s: %2$d entry updated'=>'%1$s: %2$d entri diperbarui','Replacement complete.'=>'Penggantian selesai.','This is a large replacement. %d entries were updated now and the rest will finish automatically in the background over the next few minutes.'=>'Ini adalah penggantian besar. %d entri telah diperbarui sekarang dan sisanya akan selesai secara otomatis di latar belakang dalam beberapa menit ke depan.','Google Translate v2'=>'Google Translate v2','Google Translate API Key'=>'Kunci API Google Translate','Add your API Key here...'=>'Tambahkan Kunci API Anda di sini...','Visit <a href="https://cloud.google.com/docs/authentication/api-keys" target="_blank">this link</a> to see how you can set up an API key, <strong>control API costs</strong> and set HTTP referrer restrictions.'=>'Kunjungi <a href="https://cloud.google.com/docs/authentication/api-keys" target="_blank">tautan ini</a> untuk melihat cara menyiapkan kunci API, <strong>mengontrol biaya API</strong>, dan menetapkan pembatasan referrer HTTP.','Your HTTP referrer is: %s'=>'Referrer HTTP Anda adalah: %s','There was an error with your Google Translate key.'=>'Terjadi kesalahan pada kunci Google Translate Anda.','There was an error on the server processing your Google Translate key.'=>'Terjadi kesalahan di server saat memproses kunci Google Translate Anda.','Please check your TranslatePress license key.'=>'Silakan periksa kunci lisensi TranslatePress Anda.','Create your Free Account'=>'Buat akun gratis Anda',' or '=>' atau ','Your free account includes: '=>'Akun gratis Anda mencakup: ','Access to TranslatePress AI for instant automatic translations'=>'Akses ke TranslatePress AI untuk terjemahan otomatis instan','2000 AI words to translate automatically'=>'2000 kata AI untuk diterjemahkan secara otomatis','Get more AI Words and unlock all AI features with TranslatePress Pro.'=>'Dapatkan lebih banyak kata AI dan aktifkan semua fitur AI dengan TranslatePress Pro.','Upgrade now'=>'Tingkatkan sekarang','You have a valid %s <strong>license</strong>.'=>'Anda memiliki <strong>lisensi</strong> %s yang valid.',' words remaining. '=>' kata tersisa. ','Recheck'=>'Periksa ulang','Rechecking...'=>'Memeriksa ulang...','Done.'=>'Selesai.','Manage your license & quota on the %s'=>'Kelola lisensi & kuota Anda di %s','TranslatePress.com Account Page'=>'Halaman Akun TranslatePress.com','Advanced Add-ons'=>'Add-on Lanjutan','These addons extend your translation plugin and are available in the Developer, Business and Personal plans.'=>'Addon ini memperluas plugin terjemahan Anda dan tersedia dalam paket Developer, Business, dan Personal.','SEO Pack'=>'SEO Pack','SEO support for page slug, page title, description and Facebook and Twitter social graph information. The HTML lang attribute is properly set.'=>'Dukungan SEO untuk slug halaman, judul halaman, deskripsi, serta informasi social graph Facebook dan Twitter. Atribut lang HTML diatur dengan benar.','Multiple Languages'=>'Beberapa Bahasa','Add as many languages as you need for your project to go global. Publish your language only when all your translations are done.'=>'Tambahkan bahasa sebanyak yang Anda butuhkan untuk menjadikan proyek Anda global. Terbitkan bahasa Anda hanya ketika semua terjemahan selesai.','Pro Add-ons'=>'Addon Pro','These addons extend your translation plugin and are available in the Business and Developer plans.'=>'Addon ini memperluas plugin terjemahan Anda dan tersedia dalam paket Business dan Developer.','DeepL Automatic Translation'=>'Terjemahan Otomatis DeepL','Automatically translate your website through the DeepL API.'=>'Terjemahkan situs Anda secara otomatis melalui API DeepL.','Prompts visitors to switch to their preferred language based on their browser settings or IP address and remembers the last visited language.'=>'Mendorong pengunjung untuk beralih ke bahasa pilihan mereka berdasarkan pengaturan browser atau alamat IP dan mengingat bahasa terakhir yang dikunjungi.','Translator Accounts'=>'Akun Penerjemah','Create translator accounts for new users or allow existing users that are not administrators to translate your website.'=>'Buat akun penerjemah untuk pengguna baru atau izinkan pengguna yang sudah ada dan bukan administrator untuk menerjemahkan situs Anda.','Browse As User Role'=>'Telusuri Sebagai Peran Pengguna','Navigate your website just like a particular user role would. Really useful for dynamic content or hidden content that appears for particular users.'=>'Telusuri situs Anda seperti yang dilakukan oleh peran pengguna tertentu. Sangat berguna untuk konten dinamis atau konten tersembunyi yang muncul untuk pengguna tertentu.','Navigation Based on Language'=>'Navigasi Berdasarkan Bahasa','Configure different menu items for different languages.'=>'Konfigurasikan item menu yang berbeda untuk bahasa yang berbeda.','Connect separate domains or subdomains to each of your translated versions. Strengthen your brand’s local identity and boost SEO performance for every language you support.'=>'Hubungkan domain atau subdomain terpisah ke masing-masing versi terjemahan Anda. Perkuat identitas lokal merek Anda dan tingkatkan performa SEO untuk setiap bahasa yang Anda dukung.','Enable Modules'=>'Aktifkan modul','Enable Add-on modules to extend TranslatePress and enhance the functionality of your translated site.'=>'Aktifkan modul pengaya untuk memperluas TranslatePress dan meningkatkan fungsionalitas situs Anda yang diterjemahkan.','TranslatePress Pro is active. Activate your license key to unlock the Pro add-ons below.'=>'TranslatePress Pro aktif. Aktifkan kunci lisensi Anda untuk membuka kunci add-on Pro di bawah ini.','Activate license'=>'Aktifkan lisensi','TranslatePress Pro is installed but not activated yet.'=>'TranslatePress Pro telah terinstal tetapi belum diaktifkan.','Opens your Plugins page (filtered to TranslatePress) in a new tab. Activate the TranslatePress Pro plugin there, then return to this tab — it will update automatically.'=>'Membuka halaman Plugin Anda (difilter untuk TranslatePress) di tab baru. Aktifkan plugin TranslatePress Pro di sana, lalu kembali ke tab ini — akan diperbarui secara otomatis.','Activate TranslatePress Pro ↗'=>'Aktifkan TranslatePress Pro ↗','More functionality with TranslatePress Pro.'=>'Lebih banyak fungsionalitas dengan TranslatePress Pro.','Upgrade now ↗'=>'Tingkatkan sekarang ↗','Already a Pro User?'=>'Sudah menjadi pengguna Pro?','Opens the WordPress “Add Plugins” page in a new tab. Upload and activate the TranslatePress Pro plugin there, then return to this tab — it will update automatically.'=>'Membuka halaman “Tambah Plugin” WordPress di tab baru. Unggah dan aktifkan plugin TranslatePress Pro di sana, lalu kembali ke tab ini — akan diperbarui secara otomatis.','Install TranslatePress Pro'=>'Instal TranslatePress Pro','This add-on is not available on your current plan.'=>'Pengaya ini tidak tersedia di paket Anda saat ini.','Continue'=>'Lanjutkan','The link you followed has expired. Please reload the page and try again.'=>'Tautan yang Anda ikuti telah kedaluwarsa. Silakan muat ulang halaman dan coba lagi.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=activate-license">https://translatepress.com/account</a> -> Manage Sites.'=>'Kunci lisensi Anda dinonaktifkan untuk URL ini. Aktifkan kembali dari <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=activate-license">https://translatepress.com/account</a> -> Kelola Situs.','<p><strong>License key mismatch.</strong> The license you entered doesn\'t match the TranslatePress version you have installed.</p><p>Please check that you\'ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>Kunci lisensi tidak cocok.</strong> Lisensi yang Anda masukkan tidak cocok dengan versi TranslatePress yang telah Anda instal.</p><p>Harap periksa bahwa Anda telah menginstal versi yang benar untuk lisensi Anda dari akun TranslatePress Anda.</p>','TranslatePress Account'=>'TranslatePress Account','« Go Back'=>'« Kembali','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=tp-ai">https://translatepress.com/account</a> -> Manage Sites.'=>'Kunci lisensi Anda dinonaktifkan untuk URL ini. Aktifkan kembali dari <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=tp-ai">https://translatepress.com/account</a> -> Kelola Situs.','Automatically translate your website using TranslatePress AI.'=>'Terjemahkan situs web Anda secara otomatis menggunakan TranslatePress AI.','your account.'=>'akun Anda.','Skip and continue with manual translation »'=>'Lewati dan lanjutkan dengan terjemahan manual »','Creating a free account includes: '=>'Membuat akun gratis mencakup: ','Are you a TranslatePress PRO user?'=>'Apakah Anda pengguna TranslatePress PRO?','Install TranslatePress Pro.'=>'Instal TranslatePress Pro.','Skip this step'=>'Lewati langkah ini','The email address you added is incorrect.'=>'Alamat email yang Anda tambahkan tidak benar.','Setup Complete'=>'Penyiapan Selesai','You\'re ready to start translating!'=>'Anda siap untuk mulai menerjemahkan!','You have successfully set up TranslatePress for your website.'=>'Anda telah berhasil menyiapkan TranslatePress untuk situs web Anda.','Receive '=>'Terima ','Yes, send me multilingual growth tips.'=>'Ya, kirimkan saya tips pertumbuhan multibahasa.','Start translating'=>'Mulai menerjemahkan','Sign Up and Start translating'=>'Daftar dan mulai menerjemahkan','You need to select a default language.'=>'Anda perlu memilih bahasa default.','You are trying to add an invalid default language. Please select a valid option.'=>'Anda mencoba menambahkan bahasa default yang tidak valid. Silakan pilih opsi yang valid.','Please add an additional language.'=>'Silakan tambahkan bahasa tambahan.','You are trying to add an invalid additional language. Please select a valid option.'=>'Anda mencoba menambahkan bahasa tambahan yang tidak valid. Silakan pilih opsi yang valid.','Configure Site Languages'=>'Konfigurasi Bahasa Situs','Select the default and additional languages for your website.'=>'Pilih bahasa default dan tambahan untuk situs web Anda.','You can edit your site languages at any point.'=>'Anda dapat mengedit bahasa situs Anda kapan saja.','Default Language'=>'Bahasa Bawaan','Select the language your content is written in.'=>'Pilih bahasa yang digunakan untuk konten Anda.','Additional Language'=>'Bahasa Tambahan','Choose a secondary language...'=>'Pilih bahasa sekunder...','Slug'=>'Slug','Add Language'=>'Tambah Bahasa','Choose a language...'=>'Pilih bahasa...','TranslatePress Pro is active. Activate your license key to add more languages.'=>'TranslatePress Pro aktif. Aktifkan kunci lisensi Anda untuk menambahkan lebih banyak bahasa.','Add more than two languages with TranslatePress Pro.'=>'Tambahkan lebih dari dua bahasa dengan TranslatePress Pro.','Set up Language Switcher'=>'Siapkan Pengalih Bahasa','Select the style of the language switcher. You will find more ways to display it, in plugin settings.'=>'Pilih gaya pengalih bahasa. Anda akan menemukan lebih banyak cara untuk menampilkannya, di pengaturan plugin.','Displays a small language drop-down across your website, in a corner of your choosing.'=>'Menampilkan dropdown bahasa kecil di seluruh situs web Anda, di sudut yang Anda pilih.','Switcher Location'=>'Lokasi Pengalih','Apply a Template'=>'Terapkan template','You can customize the design later'=>'Anda dapat menyesuaikan desain nanti','Default Template'=>'Template bawaan','Default'=>'Bawaan','Dark Template'=>'Template gelap','Border Template'=>'Template berbingkai','Border'=>'Bingkai','Transparent Template'=>'Template transparan','Transparent'=>'Transparan','Welcome to TranslatePress'=>'Selamat datang di TranslatePress','Quick guided setup to configure TranslatePress in no time!'=>'Panduan penyiapan cepat untuk mengonfigurasi TranslatePress dalam waktu singkat!','It takes less than a minute.'=>'Hanya membutuhkan waktu kurang dari satu menit.','Scanning item %1$d of %2$d...'=>'Memindai item %1$d dari %2$d...','Manually translated'=>'Diterjemahkan secara manual','Automatically translated'=>'Diterjemahkan secara otomatis','Gettext file translation'=>'Terjemahan file Gettext','Not translated'=>'Belum diterjemahkan','Bulk Actions'=>'Tindakan massal','Delete entries'=>'Hapus entri','Filter'=>'Saring','Clear filters'=>'Bersihkan filter','Language'=>'Bahasa','Add New'=>'Tambah Baru','Rescan plugins and theme for strings'=>'Pindai ulang plugin dan tema untuk string','Scanning plugins and theme for strings...'=>'Memindai plugin dan tema untuk string...','Plugins and theme scan is complete'=>'Pemindaian plugin dan tema selesai','Plugins and theme scan did not finish due to an error'=>'Pemindaian plugin dan tema tidak selesai karena kesalahan','Import / Export'=>'Impor / Ekspor','See More'=>'Lihat Selengkapnya','See Less'=>'Lihat Lebih Sedikit','Apply'=>'Terapkan','No strings match your query.'=>'Tidak ada string yang cocok dengan kueri Anda.','Try to rescan plugins and theme for strings.'=>'Coba pindai ulang plugin dan tema untuk string.','An error occurred while loading results. Most likely you were logged out. Reload page?'=>'Terjadi kesalahan saat memuat hasil. Besar kemungkinan Anda telah keluar log. Muat ulang halaman?','found in translation'=>'ditemukan dalam terjemahan','Select All'=>'Pilih Semua','Select Visible'=>'Pilih yang Terlihat','You are about to perform this action on all the strings matching your filter, not just the visibly checked. To perform the action only to the visible strings click "Select Visible" from the table header dropdown.'=>'Anda akan melakukan tindakan ini pada semua string yang cocok dengan filter Anda, bukan hanya yang terlihat. Untuk melakukan tindakan hanya pada string yang terlihat, klik "Pilih yang Terlihat" dari menu tarik-turun header tabel.','You are about to perform this action only on the visible strings. To perform the action on all the strings matching the filter click "Select All" from the table header dropdown.'=>'Anda akan melakukan tindakan ini hanya pada string yang terlihat. Untuk melakukan tindakan pada semua string yang cocok dengan filter, klik "Pilih Semua" dari menu tarik-turun header tabel.','To continue please type the word:'=>'Untuk melanjutkan, silakan ketik kata:','The word typed was incorrect. Action was cancelled.'=>'Kata yang diketik salah. Tindakan dibatalkan.','Warning: This action cannot be undone. Deleting a string will remove its current translation. The original string will appear again in this interface after TranslatePress detects it. This action is NOT equivalent to excluding the string from being translated again.'=>'Peringatan: Tindakan ini tidak dapat dibatalkan. Menghapus string akan menghapus terjemahannya saat ini. String asli akan muncul kembali di antarmuka ini setelah TranslatePress mendeteksinya. Tindakan ini TIDAK setara dengan mengecualikan string agar tidak diterjemahkan lagi.','%d original entries and their translations were deleted.'=>'%d entri asli dan terjemahannya telah dihapus.','Navigate to next page'=>'Navigasi ke halaman berikutnya','Navigate to previous page'=>'Navigasi ke halaman sebelumnya','Navigate to first page'=>'Navigasi ke halaman pertama','Navigate to last page'=>'Navigasi ke halaman terakhir','Type a page number to navigate to'=>'Ketik nomor halaman untuk dinavigasi','Incorrect page number. Type a page number between 1 and total number of pages'=>'Nomor halaman salah. Ketik nomor halaman antara 1 dan jumlah total halaman','Search original and translated strings containing typed keywords while also matching selected filters. Place string in quotes for exact match: "string"'=>'Cari string asli dan terjemahan yang berisi kata kunci yang diketik sambil juga mencocokkan filter yang dipilih. Letakkan string dalam tanda kutip untuk kecocokan tepat: "string"','Filter strings according to selected translation status, filters and keywords and selected filters'=>'Saring string berdasarkan status terjemahan yang dipilih, filter dan kata kunci, serta filter yang dipilih.','Removes selected filters'=>'Hapus filter yang dipilih','See options for selecting all strings'=>'Lihat opsi untuk memilih semua string','Click to sort strings by this column'=>'Klik untuk mengurutkan string berdasarkan kolom ini','The ID of the WordPress post where this string was detected. Empty if the string is not associated with a specific post.'=>'ID pos WordPress tempat string ini terdeteksi. Kosong jika string tidak dikaitkan dengan pos tertentu.','Language in which the translation status filter applies. Leave unselected for the translation status to apply to ANY language'=>'Bahasa tempat filter status terjemahan diterapkan. Biarkan tidak dipilih agar status terjemahan diterapkan pada SEMUA bahasa','Search'=>'Cari','Slugs that are not found in either one of the other categories.'=>'Slug yang tidak ditemukan di salah satu pun kategori lainnya.','Plugins and Theme String Translation'=>'Terjemahan String Plugin dan Tema','Gettext'=>'Gettext','Search Gettext Strings'=>'Cari String Gettext','Original String'=>'String Asli','Filter by domain'=>'Filter berdasarkan domain','Filter by type'=>'Filter berdasarkan jenis','Email text'=>'Teks email','Emails String Translation'=>'Terjemahan String Email','Emails'=>'Email','Search Email Strings'=>'Cari String Email','User Inputted String Translation'=>'Terjemahan String Input Pengguna','Regular'=>'Reguler','Search Regular Strings'=>'Cari String Reguler','Filter by Translation Block'=>'Filter berdasarkan Blok Terjemahan','String Translation Editor'=>'Editor Terjemahan String','Every minute'=>'Setiap menit','Could not load the background task.'=>'Tidak dapat memuat tugas latar belakang.','Waiting to start background processing...'=>'Menunggu untuk memulai pemrosesan latar belakang...','Background processing could not start.'=>'Pemrosesan latar belakang tidak dapat dimulai.','Background processing completed.'=>'Pemrosesan latar belakang selesai.','A previous batch item failed.'=>'Item batch sebelumnya gagal.','TranslatePress background processing did not complete successfully.'=>'Pemrosesan latar belakang TranslatePress tidak berhasil diselesaikan.','Error: %s'=>'Kesalahan: %s','You do not have permission to view this task status.'=>'Anda tidak memiliki izin untuk melihat status tugas ini.','Invalid batch task.'=>'Tugas batch tidak valid.','TranslatePress is processing a background task.'=>'TranslatePress sedang memproses tugas latar belakang.','TranslatePress background processing completed successfully.'=>'Pemrosesan latar belakang TranslatePress berhasil diselesaikan.','Processing %s...'=>'Memproses %s...','%s is optimizing gettext database tables in the background. Translations continue to work while this runs.'=>'%s sedang mengoptimalkan tabel basis data gettext di latar belakang. Terjemahan tetap berfungsi selama proses ini berjalan.','TranslatePress gettext database optimization completed successfully.'=>'Optimasi basis data gettext TranslatePress berhasil diselesaikan.','TranslatePress has detected and cleaned up some failed translation entries in your database following %s. No further action is required.'=>'TranslatePress telah mendeteksi dan membersihkan beberapa entri terjemahan yang gagal di basis data Anda setelah %s. Tidak diperlukan tindakan lebih lanjut.','an isolated incident'=>'sebuah insiden terisolasi','Update aborted! Unknown gettext lookup hash migration phase: %s.'=>'Pembaruan dibatalkan! Fase migrasi hash pencarian gettext tidak dikenal: %s.','Update aborted! Could not find an available gettext original_id index name for table %s.'=>'Pembaruan dibatalkan! Tidak dapat menemukan nama indeks original_id gettext yang tersedia untuk tabel %s.','Update aborted! Gettext lookup hash migration cannot process invalid ID %1$d in table %2$s. Repair the table ID schema and retry.'=>'Pembaruan dibatalkan! Migrasi hash pencarian gettext tidak dapat memproses ID tidak valid %1$d di tabel %2$s. Perbaiki skema ID tabel dan coba lagi.','Update aborted! Table %1$s still references %2$d duplicate gettext original ids.'=>'Pembaruan dibatalkan! Tabel %1$s masih mereferensikan %2$d ID original gettext yang duplikat.','Update aborted! Gettext original meta still references %d duplicate original ids.'=>'Pembaruan dibatalkan! Meta original gettext masih mereferensikan %d ID original yang duplikat.','Gettext database optimization completed.'=>'Optimasi basis data gettext selesai.','Deduplicating gettext translation tables...'=>'Menghapus duplikat tabel terjemahan gettext...','Migrating gettext original lookup hashes...'=>'Memigrasi hash pencarian original gettext...','Preparing the gettext originals lookup index...'=>'Mempersiapkan indeks pencarian teks asli gettext...','Updating gettext runtime statuses...'=>'Memperbarui status runtime gettext...','Finishing gettext database optimization...'=>'Menyelesaikan optimasi basis data gettext...','Updating gettext runtime statuses for language %s...'=>'Memperbarui status runtime gettext untuk bahasa %s...','Resolving missing gettext original ids in %s...'=>'Menyelesaikan ID asli gettext yang hilang dalam %s...','Preparing gettext table %s...'=>'Menyiapkan tabel gettext %s...','Removing invalid gettext rows from %s...'=>'Menghapus baris gettext yang tidak valid dari %s...','Prepared gettext original ids in %s...'=>'ID asli gettext telah disiapkan dalam %s...','Normalizing plural forms in %s...'=>'Menormalkan bentuk jamak dalam %s...','Processing duplicate gettext rows in %s...'=>'Memproses baris gettext duplikat dalam %s...','Building duplicate gettext map for %s...'=>'Membuat peta duplikat gettext untuk %s...','Verifying gettext table %s...'=>'Memverifikasi tabel gettext %s...','Deleting duplicate gettext rows from %s...'=>'Menghapus baris gettext duplikat dari %s...','Rechecking duplicate gettext rows in %s...'=>'Memeriksa ulang baris gettext duplikat dalam %s...','Adding unique gettext index for %s...'=>'Menambahkan indeks unik gettext untuk %s...','Finished gettext table %s.'=>'Tabel gettext %s selesai.','License'=>'Lisensi','Your License Key is valid.'=>'Kunci lisensi Anda valid.','Your License Key is invalid.'=>'Kunci lisensi Anda tidak valid.','Your License has expired.'=>'Lisensi Anda telah kedaluwarsa.','Deactivate License'=>'Nonaktifkan Lisensi','Add a license key'=>'Tambahkan kunci lisensi','License Key'=>'Kunci Lisensi','Manage your license in your %1$s.'=>'Kelola lisensi Anda di %1$s Anda.','Don’t have a TranslatePress AI License Key?'=>'Belum memiliki Kunci Lisensi TranslatePress AI?','Get a free License Today'=>'Dapatkan Lisensi Gratis Hari Ini','Add your License Key'=>'Tambahkan Kunci Lisensi Anda','Add your License Key to unlock all premium features. Find the License Key in your'=>'Tambahkan Kunci Lisensi Anda untuk membuka semua fitur premium. Temukan Kunci Lisensi di','Your license is valid and active.'=>'Lisensi Anda valid dan aktif.','TranslatePress License'=>'Lisensi TranslatePress','In order to enable Automatic Translation using TranslatePress AI, you need a license key by creating a free account.'=>'Untuk mengaktifkan Terjemahan Otomatis menggunakan TranslatePress AI, Anda memerlukan kunci lisensi dengan membuat akun gratis.','In order to enable Automatic Translation using TranslatePress AI, please enter your license key from'=>'Untuk mengaktifkan Terjemahan Otomatis menggunakan TranslatePress AI, silakan masukkan kunci lisensi Anda dari','Get Your Free TranslatePress AI License'=>'Dapatkan Lisensi TranslatePress AI Gratis Anda','Generate License'=>'Hasilkan Lisensi','Get a Free AI License'=>'Dapatkan Lisensi AI Gratis','This website is already activated under a free license. Each website can only use one free license.'=>'Situs web ini sudah diaktifkan dengan lisensi gratis. Setiap situs web hanya dapat menggunakan satu lisensi gratis.','This website is already activated under a free license. Each website can only use one free license. Please upgrade to a premium plan for more TranslatePress AI words from %1$s your account %2$s.'=>'Situs web ini sudah diaktifkan dengan lisensi gratis. Setiap situs web hanya dapat menggunakan satu lisensi gratis. Silakan tingkatkan ke paket premium untuk mendapatkan lebih banyak kata TranslatePress AI dari %1$s akun Anda %2$s.','Debug Data for License Checking'=>'Data Debug untuk Pemeriksaan Lisensi','Debug Data for License Activation'=>'Data Debug untuk Aktivasi Lisensi','Please install and activate the TranslatePress - Multilingual plugin'=>'Harap instal dan aktifkan plugin TranslatePress - Multilingual','Please update the TranslatePress - Multilingual plugin to version %1$s or higher to ensure %2$s functions correctly.'=>'Harap perbarui plugin TranslatePress - Multilingual ke versi %1$s atau lebih tinggi untuk memastikan %2$s berfungsi dengan benar.','Please update TranslatePress - Multilingual to version %2$s or newer. Your currently installed version of TranslatePress - Multilingual is no longer compatible with the current version of %1$s.'=>'Harap perbarui TranslatePress - Multilingual ke versi %2$s atau lebih baru. Versi TranslatePress - Multilingual yang terpasang saat ini tidak lagi kompatibel dengan versi %1$s saat ini.','All TranslatePress functionalities are disabled until then.'=>'Semua fungsionalitas TranslatePress dinonaktifkan hingga saat itu.','Update Now'=>'Perbarui Sekarang','This TranslatePress add-on has been migrated to the main plugin and is no longer used. You can delete it.'=>'Add-on TranslatePress ini telah dimigrasikan ke plugin utama dan tidak lagi digunakan. Anda dapat menghapusnya.','<strong>TranslatePress</strong> requires at least PHP version 5.6.20+ to run. It is the <a href="%s">minimum requirement of the latest WordPress version</a>. Please contact your server administrator to update your PHP version.'=>'<strong>TranslatePress</strong> memerlukan setidaknya versi PHP 5.6.20+ untuk berjalan. Ini adalah <a href="%s">persyaratan minimum versi WordPress terbaru</a>. Harap hubungi administrator server Anda untuk memperbarui versi PHP Anda.','TranslatePress Add-ons'=>'Add-on TranslatePress','You must first purchase this version to have access to the addon %1$shere%2$s'=>'Anda harus terlebih dahulu membeli versi ini untuk mengakses add-on %1$sdi sini%2$s','You need an active license to have access to the addon. Renew or purchase a new one %1$shere%2$s.'=>'Anda memerlukan lisensi aktif untuk mengakses addon. Perbarui atau beli yang baru %1$sdi sini%2$s.','Please %1$senter your license%2$s key first, to activate this addon.'=>'Silakan %1$smasukkan kunci lisensi Anda%2$s terlebih dahulu untuk mengaktifkan addon ini.','SEO Pack (Legacy)'=>'SEO Pack (Legacy)','SEO support for page slug, page title, description and facebook and twitter social graph information. The HTML lang attribute is properly set.'=>'Dukungan SEO untuk slug halaman, judul halaman, deskripsi, serta informasi social graph Facebook dan Twitter. Atribut lang HTML diatur dengan benar.','Recommended Plugins'=>'Plugin yang Direkomendasikan','A short list of plugins you can use to extend your website.'=>'Daftar singkat plugin yang dapat Anda gunakan untuk memperluas situs web Anda.','Profile Builder'=>'Profile Builder','Capture more user information on the registration form with the help of Profile Builder\'s custom user profile fields and/or add an Email Confirmation process to verify your customers accounts.'=>'Kumpulkan lebih banyak informasi pengguna di formulir pendaftaran dengan bantuan bidang profil pengguna kustom dari Profile Builder dan/atau tambahkan proses Konfirmasi Email untuk memverifikasi akun pelanggan Anda.','Paid Member Subscriptions'=>'Paid Member Subscriptions','Accept user payments, create subscription plans and restrict content on your membership site.'=>'Terima pembayaran pengguna, buat paket langganan, dan batasi konten di situs keanggotaan Anda.','WP Webhooks Automator'=>'WP Webhooks Automator','Create no-code automations and workflows on your WordPress site. Easily connect your plugins, sites and apps together.'=>'Buat otomasi dan alur kerja tanpa kode di situs WordPress Anda. Hubungkan plugin, situs, dan aplikasi Anda dengan mudah.','Save Changes'=>'Simpan Perubahan','Account Page'=>'Halaman Akun','You can get one for %1$sfree%2$s, by creating a free account. It includes:'=>'Anda bisa mendapatkannya %1$sgratis%2$s dengan membuat akun gratis. Termasuk:','Debug Information'=>'Informasi Debug','Get more AI words and unlock all features with TranslatePress Pro.'=>'Dapatkan lebih banyak kata AI dan buka kunci semua fitur dengan TranslatePress Pro.','Already purchased a Premium version?'=>'Sudah membeli versi Premium?','Go to your %1$s'=>'Buka %1$s Anda','TranslatePress.com Account'=>'Akun TranslatePress.com','Download & Install the Pro plugin'=>'Unduh & Instal plugin Pro','Learn More'=>'Pelajari Selengkapnya','TranslatePress Errors'=>'Kesalahan TranslatePress','There are no logged errors.'=>'Tidak ada kesalahan yang tercatat.','WordPress Translation Plugin'=>'Plugin Terjemahan WordPress','Back to Glossary'=>'Kembali ke Glosarium','Search Existing Translations'=>'Cari Terjemahan yang Ada','Search the existing dictionary entries to see how a term is currently translated in each language.'=>'Cari entri kamus yang ada untuk melihat bagaimana sebuah istilah saat ini diterjemahkan dalam setiap bahasa.','To fully explore all the translations, use %s.'=>'Untuk menjelajahi semua terjemahan sepenuhnya, gunakan %s.','Search existing translations'=>'Cari terjemahan yang ada','Replace Existing Translations'=>'Ganti Terjemahan yang Ada','The requested glossary term could not be found. It may have been deleted.'=>'Istilah glosarium yang diminta tidak dapat ditemukan. Mungkin sudah dihapus.','&laquo; Back to Glossary'=>'&laquo; Kembali ke Glosarium','For each language, enter the current (existing) translation you want to find; every case-insensitive occurrence in the stored translations will be replaced with the new translation, keeping the original capitalization.'=>'Untuk setiap bahasa, masukkan terjemahan saat ini (yang ada) yang ingin Anda temukan; setiap kemunculan yang tidak peka huruf besar/kecil dalam terjemahan yang tersimpan akan diganti dengan terjemahan baru, dengan mempertahankan kapitalisasi asli.','Leaving a language field empty will skip that language entirely (no changes will be made for it). Only one existing translation per language can be entered at a time. If you have multiple translations to replace for the same language, simply run the replacement again with the next value.'=>'Membiarkan bidang bahasa kosong akan melewati bahasa tersebut sepenuhnya (tidak ada perubahan yang akan dilakukan untuk bahasa tersebut). Hanya satu terjemahan yang ada per bahasa yang dapat dimasukkan dalam satu waktu. Jika Anda memiliki beberapa terjemahan yang ingin diganti untuk bahasa yang sama, cukup jalankan penggantian lagi dengan nilai berikutnya.','The "Existing translation" is not the term in the default language, but rather the already existing wrong translation you want to correct.'=>'"Terjemahan yang ada" bukan istilah dalam bahasa default, melainkan terjemahan yang sudah ada dan salah yang ingin Anda perbaiki.','Existing translation'=>'Terjemahan yang ada','New translation'=>'Terjemahan baru','Replace in existing translations'=>'Ganti dalam terjemahan yang ada','Glossary is available only with the TranslatePress AI engine.'=>'Glosarium hanya tersedia dengan mesin TranslatePress AI.','Select the %s automatic translation engine to add and manage glossary terms. For other translation engines (such as DeepL or Google Translate), glossary functions are available in the translation provider’s dashboard.'=>'Pilih mesin penerjemahan otomatis %s untuk menambah dan mengelola istilah glosarium. Untuk mesin penerjemahan lainnya (seperti DeepL atau Google Translate), fungsi glosarium tersedia di dasbor penyedia terjemahan.','Add Glossary Term'=>'Tambah Istilah Glosarium','Define words or phrases that should not be translated automatically, and optionally provide replacements per language.'=>'Tentukan kata atau frasa yang tidak boleh diterjemahkan secara otomatis, dan secara opsional berikan pengganti untuk setiap bahasa.','The original word or phrase in the default language.'=>'Kata atau frasa asli dalam bahasa default.','Add Term'=>'Tambah Istilah','Search glossary terms'=>'Cari istilah glosarium','Search terms'=>'Cari istilah','Search Glossary'=>'Cari Glosarium','Loading…'=>'Memuat…','To edit existing translations, use the %s.'=>'Untuk mengedit terjemahan yang sudah ada, gunakan %s.','Language Switcher update notice'=>'Pemberitahuan pembaruan pengalih bahasa','Legacy language switcher is currently enabled'=>'Pengalih bahasa lawas saat ini diaktifkan','We’ve upgraded the switcher for richer customization and a better user experience.<br>In order to use the new configurator, turn off <strong>Load legacy language switcher</strong>.'=>'Kami telah meningkatkan pengalih bahasa untuk kustomisasi yang lebih kaya dan pengalaman pengguna yang lebih baik.<br>Untuk menggunakan konfigurator baru, nonaktifkan <strong>Muat pengalih bahasa lawas</strong>.','Note: You can switch back anytime from <strong>Advanced Settings → <a href="%s">Troubleshooting</a></strong>.'=>'Catatan: Anda dapat beralih kembali kapan saja dari <strong>Pengaturan Lanjutan → <a href="%s">Pemecahan Masalah</a></strong>.','Enable the new switcher'=>'Aktifkan pengalih baru','Get a translation volume estimate with a detailed breakdown per page'=>'Dapatkan estimasi volume terjemahan dengan rincian detail per halaman','Find how many translatable words are on your website'=>'Cari tahu berapa banyak kata yang dapat diterjemahkan di situs web Anda','<strong>DeepL</strong> automatic translation is available as a <a href="%1$s" target="_blank" title="%2$s">%2$s</a>.'=>'Terjemahan otomatis <strong>DeepL</strong> tersedia sebagai <a href="%1$s" target="_blank" title="%2$s">%2$s</a>.','By upgrading you\'ll get access to all paid add-ons, premium support and help fund the future development of TranslatePress.'=>'Dengan upgrade, Anda akan mendapatkan akses ke semua add-on berbayar, dukungan premium, dan membantu mendanai pengembangan TranslatePress di masa depan.','To use <strong>DeepL</strong> for automatic translation, activate this Pro add-on from the <a href="%1$s" target="_self" title="%2$s">%2$s</a>.'=>'Untuk menggunakan <strong>DeepL</strong> untuk terjemahan otomatis, aktifkan add-on Pro ini dari <a href="%1$s" target="_self" title="%2$s">%2$s</a>.','Please note that DeepL API usage is paid separately. See <a href="https://www.deepl.com/pro.html#developer">DeepL pricing information</a>.'=>'Harap dicatat bahwa penggunaan API DeepL dikenakan biaya secara terpisah. Lihat <a href="https://www.deepl.com/pro.html#developer">informasi harga DeepL</a>.','TranslatePress Pro Add-ons'=>'Add-on TranslatePress Pro','Test API credentials'=>'Uji Kredensial API','Check if the selected translation engine is configured correctly.'=>'Periksa apakah mesin penerjemahan yang dipilih dikonfigurasi dengan benar.','Alternative Engines'=>'Mesin Alternatif','More info'=>'Info selengkapnya','Switch to TranslatePress AI'=>'Beralih ke TranslatePress AI','Integrate machine translation directly with your WordPress website.'=>'Integrasikan terjemahan mesin langsung dengan situs web WordPress Anda.','Choose which engine you want to use in order to %1$s automatically translate your website.'=>'Pilih mesin yang ingin Anda gunakan agar %1$s secara otomatis menerjemahkan situs web Anda.','Automatically Translate Slugs'=>'Penerjemahan Slug Otomatis','Generate automatic translations of slugs for posts, pages and Custom Post Types.<br/>The slugs will be automatically translated starting with the second refresh of each page.'=>'Hasilkan terjemahan otomatis slug untuk pos, halaman, dan Custom Post Type.<br/>Slug akan diterjemahkan secara otomatis mulai dari penyegaran kedua setiap halaman.','This feature is only available in the paid version. Upgrade TranslatePress and unlock more premium features.'=>'Fitur ini hanya tersedia di versi berbayar. Tingkatkan TranslatePress dan buka kunci lebih banyak fitur premium.','Requires <a href="%s" title="TranslatePress Add-on SEO Pack documentation" target="_blank">SEO Pack Add-on</a> to be installed and activated.'=>'Memerlukan <a href="%s" title="TranslatePress Add-on SEO Pack documentation" target="_blank">SEO Pack Add-on</a> untuk diinstal dan diaktifkan.','Automatic Translation Settings'=>'Pengaturan Terjemahan Otomatis','AI Words Low Notification'=>'Notifikasi Kata AI Rendah','Receive an email notification when your TranslatePress AI word count drops below the specified threshold.'=>'Terima notifikasi email ketika jumlah kata TranslatePress AI Anda turun di bawah ambang batas yang ditentukan.','This feature is only available when using the TranslatePress AI translation engine.'=>'Fitur ini hanya tersedia saat menggunakan mesin terjemahan TranslatePress AI.','Notification Email'=>'Email Notifikasi','The email address where the low AI words notification will be sent.'=>'Alamat email tempat notifikasi kata AI rendah akan dikirim.','Word Threshold'=>'Ambang Batas Kata','words'=>'kata','You will be notified when remaining AI words drop below this number.'=>'Anda akan diberi tahu ketika sisa kata AI turun di bawah angka ini.','Block Crawlers'=>'Blokir Crawler','Block crawlers from triggering automatic translations on your website.<br>This will not prevent crawlers from accessing this site\'s pages.'=>'Mencegah crawler memicu terjemahan otomatis di situs web Anda.<br>Ini tidak akan mencegah crawler mengakses halaman situs ini.','Limit machine translation / characters per day'=>'Batasi terjemahan mesin / karakter per hari','Add a limit to the number of automatically translated characters so you can better budget your project.'=>'Tambahkan batas pada jumlah karakter yang diterjemahkan secara otomatis agar Anda dapat mengatur anggaran proyek Anda dengan lebih baik.','characters per day'=>'karakter per hari','Today\'s Character Count: '=>'Jumlah Karakter Hari Ini: ','Log machine translation queries.'=>'Catat kueri terjemahan mesin.','Only enable for testing purposes. Can impact performance.<br>All records are stored in the wp_trp_machine_translation_log database table. Use a plugin like <a href="https://wordpress.org/plugins/wp-data-access/" target="_blank">WP Data Access</a> to browse the logs or directly from your database manager (PHPMyAdmin, etc.)'=>'Hanya aktifkan untuk tujuan pengujian. Dapat memengaruhi performa.<br>Semua catatan disimpan di tabel basis data wp_trp_machine_translation_log. Gunakan plugin seperti <a href="https://wordpress.org/plugins/wp-data-access/" target="_blank">WP Data Access</a> untuk menelusuri log atau langsung dari pengelola basis data Anda (PHPMyAdmin, dll.)','Test API Credentials'=>'Uji Kredensial API','HTTP Referrer: '=>'HTTP Referrer: ','Use this HTTP Referrer if the API lets you restrict key usage from its Dashboard.'=>'Gunakan HTTP Referrer ini jika API memungkinkan Anda membatasi penggunaan kunci dari Dasbornya.','Request URL'=>'URL Permintaan','Request Headers'=>'Header Permintaan','Request Body'=>'Body Permintaan','Response'=>'Respons','Response Body'=>'Isi Respons','Entire Response From wp_remote_get():'=>'Respons lengkap dari wp_remote_get():','Select the languages you wish to make your website available in.'=>'Pilih bahasa yang ingin Anda sediakan untuk situs web Anda.','Formality'=>'Formalitas','Code'=>'Kode','Formal'=>'Formal','Informal'=>'Informal','This language does not support formality. '=>'Bahasa ini tidak mendukung formalitas. ','Are you sure you want to remove this language?'=>'Apakah Anda yakin ingin menghapus bahasa ini?','Custom Languages'=>'Bahasa Kustom','Adding more than two languages is a paid feature. Upgrade TranslatePress and unlock more premium features.'=>'Menambah lebih dari dua bahasa merupakan fitur berbayar. Tingkatkan TranslatePress dan buka lebih banyak fitur premium.','Please %1$senter your license%2$s key first to add more languages.'=>'Silakan %1$smasukkan kunci lisensi Anda%2$s terlebih dahulu untuk menambah bahasa.','You need an active license to add more languages. Verify in your %1$saccount%2$s that your license is valid'=>'Anda memerlukan lisensi aktif untuk menambah bahasa. Verifikasi di %1$sakun%2$s Anda bahwa lisensi Anda valid.','To Add more languages activate the Multiple Languages Addon'=>'Untuk menambah bahasa, aktifkan Add-on Multiple Languages','Website Languages'=>'Bahasa Situs Web','WARNING. Changing the default language will invalidate existing translations.'=>'PERINGATAN. Mengubah bahasa bawaan akan membuat terjemahan yang ada tidak valid.','Even changing from en_US to en_GB, because they are treated as two different languages.'=>'Bahkan mengubah dari en_US ke en_GB, karena keduanya dianggap sebagai dua bahasa berbeda.','In most cases changing the default flag is all it is needed: '=>'Dalam kebanyakan kasus, mengubah bendera bawaan sudah cukup: ','replace the default flag'=>'ganti bendera bawaan','Re-run Setup Wizard'=>'Jalankan Ulang Panduan Penyiapan','The Setup wizard allows you to quickly setup TranslatePress. You can initiate it at any time.'=>'Panduan penyiapan memungkinkan Anda menyiapkan TranslatePress dengan cepat. Anda dapat memulainya kapan saja.','Language Settings'=>'Pengaturan Bahasa','Use Native language name'=>'Gunakan nama bahasa asli','Check if you want to display languages in their native names. Otherwise, languages will be displayed in English.'=>'Centang jika Anda ingin menampilkan bahasa dalam nama aslinya. Jika tidak, bahasa akan ditampilkan dalam bahasa Inggris.','Use a subdirectory for the default language'=>'Gunakan subdirektori untuk bahasa bawaan','Check if you want to add the subdirectory in the URL for the default language.</br>By checking this option, the default language seen by website visitors will become the first one in the "All Languages" list.'=>'Centang jika Anda ingin menambahkan subdirektori dalam URL untuk bahasa bawaan.</br>Dengan mencentang opsi ini, bahasa bawaan yang dilihat pengunjung situs web akan menjadi yang pertama dalam daftar "Semua Bahasa".','Force language in custom links'=>'Paksakan bahasa dalam tautan kustom','Select Yes if you want to force custom links without language encoding to keep the currently selected language.'=>'Pilih Ya jika Anda ingin memaksa tautan kustom tanpa pengkodean bahasa untuk mempertahankan bahasa yang sedang dipilih.','Shortcode '=>'Shortcode ','Use shortcode on any page or widget.'=>'Gunakan shortcode di halaman atau widget apa pun.','You can also add the <a href="%s" title="Language Switcher Block Documentation">Language Switcher Block</a> in the WP Gutenberg Editor.'=>'Anda juga dapat menambahkan <a href="%s" title="Language Switcher Block Documentation">Blok Pengalih Bahasa</a> di Editor WP Gutenberg.','Menu item'=>'Item menu','Go to  %1$s Appearance -> Menus%2$s to add languages to the Language Switcher in any menu.'=>'Pergi ke  %1$s Tampilan -> Menu%2$s untuk menambahkan bahasa ke Pengalih Bahasa di menu apa pun.','Learn more in our documentation.'=>'Pelajari lebih lanjut di dokumentasi kami.','Floating language selection'=>'Pemilihan bahasa mengambang','Add a floating dropdown that follows the user on every page.'=>'Tambahkan dropdown mengambang yang mengikuti pengguna di setiap halaman.','Show "Powered by TranslatePress"'=>'Tampilkan "Powered by TranslatePress"','Show the small "Powered by TranslatePress" label in the floater language switcher.'=>'Tampilkan label kecil "Powered by TranslatePress" di pengalih bahasa mengambang.','5 Days to Better Multilingual Websites'=>'5 Hari Menuju Situs Web Multibahasa yang Lebih Baik','%sJoin our FREE & EXCLUSIVE onboarding course%s and learn how to grow your multilingual traffic, reach international markets, and save time & money while getting the most out of TranslatePress!'=>'%sIkuti kursus onboarding GRATIS & EKSKLUSIF kami%s dan pelajari cara meningkatkan trafik multibahasa Anda, menjangkau pasar internasional, serta menghemat waktu & uang sambil memaksimalkan TranslatePress!','Invalid email address'=>'Alamat email tidak valid','Your email'=>'Email Anda','Sign me up!'=>'Daftarkan saya!','Sign up with your email address and receive a 5-part email guide to help you maximize the power of TranslatePress.'=>'Daftar dengan alamat email Anda dan terima panduan email 5-bagian untuk membantu Anda memaksimalkan potensi TranslatePress.','Dismiss email course notification'=>'Tutup notifikasi kursus email','Hey %s,<br>Never miss an important update - opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Hai %s,<br>Jangan lewatkan pembaruan penting - aktifkan notifikasi pembaruan keamanan dan fitur, serta pelacakan diagnostik yang tidak sensitif.','Allow & Continue'=>'Izinkan & Lanjutkan','Skip'=>'Lewati','This will allow TranslatePress to:'=>'Ini akan memungkinkan TranslatePress untuk:','Your profile overview'=>'Ringkasan profil Anda','Name and email address'=>'Nama dan alamat email','Admin Notices'=>'Pemberitahuan Admin','Updates, announcements, marketing, no spam'=>'Pembaruan, pengumuman, pemasaran, tidak ada spam','Plugin status & settings'=>'Status & pengaturan plugin','Active, Deactivated, installed version and settings'=>'Aktif, nonaktif, versi terinstal, dan pengaturan','Privacy Policy'=>'Kebijakan Privasi','Terms of Service'=>'Ketentuan Layanan','Support'=>'Dukungan','Add Extra AI Words'=>'Tambah Kata AI Ekstra','<strong>IMPORTANT NOTE:</strong> Before performing this action it is strongly recommended to first backup the database.'=>'<strong>CATATAN PENTING:</strong> Sebelum melakukan tindakan ini, sangat disarankan untuk membuat cadangan basis data terlebih dahulu.','IMPORTANT: It is strongly recommended to first backup the database!! Are you sure you want to continue?'=>'PENTING: Sangat disarankan untuk membuat cadangan basis data terlebih dahulu!! Apakah Anda yakin ingin melanjutkan?','Operations to perform'=>'Operasi yang akan dilakukan','Remove CDATA for original and dictionary strings'=>'Hapus CDATA untuk string asli dan string kamus','Removes CDATA from trp_original_strings and trp_dictionary_* tables.<br>This type of content should not be detected by TranslatePress. It might have been introduced in the database in older versions of the plugin.'=>'Menghapus CDATA dari tabel trp_original_strings dan trp_dictionary_*.<br>Jenis konten ini seharusnya tidak terdeteksi oleh TranslatePress. Konten ini mungkin telah dimasukkan ke dalam basis data pada versi plugin yang lebih lama.','Remove untranslated links from dictionary tables'=>'Hapus tautan yang belum diterjemahkan dari tabel kamus','Removes untranslated links and images from all trp_dictionary_* tables. These tables contain translations for user-inputted strings such as post content, post title, menus etc.'=>'Menghapus tautan dan gambar yang belum diterjemahkan dari semua tabel trp_dictionary_*. Tabel-tabel ini berisi terjemahan untuk string yang diinput pengguna seperti konten pos, judul pos, menu, dll.','Remove duplicate rows for gettext strings'=>'Hapus baris duplikat untuk string gettext','Cleans up all trp_gettext_* tables of duplicate rows. These tables contain translations for themes and plugin strings.'=>'Membersihkan semua tabel trp_gettext_* dari baris duplikat. Tabel-tabel ini berisi terjemahan untuk string tema dan plugin.','Remove duplicate rows for dictionary strings'=>'Hapus baris duplikat untuk string kamus','Cleans up all trp_dictionary_* tables of duplicate rows. These tables contain translations for user-inputted strings such as post content, post title, menus etc.'=>'Membersihkan semua tabel trp_dictionary_* dari baris duplikat. Tabel-tabel ini berisi terjemahan untuk string yang diinput pengguna seperti konten pos, judul pos, menu, dll.','Remove duplicate rows for original dictionary strings'=>'Hapus baris duplikat untuk string kamus asli','Cleans up all trp_original_strings table of duplicate rows. This table contains strings in the default language, without any translation.<br>The trp_original_meta table, which contains meta information that refers to the post parent’s ID, is also regenerated.<br>Such duplicates can appear in exceptional situations of unexpected behavior.'=>'Membersihkan tabel trp_original_strings dari baris duplikat. Tabel ini berisi string dalam bahasa default, tanpa terjemahan apa pun.<br>Tabel trp_original_meta, yang berisi informasi meta yang mengacu pada ID induk pos, juga diregenerasi.<br>Duplikat seperti itu dapat muncul dalam situasi pengecualian akibat perilaku tak terduga.','Replace gettext strings that have original ID NULL with the correct original IDs'=>'Ganti string gettext yang memiliki ID asli NULL dengan ID asli yang benar','Fixes an edge case issue where some gettext strings have the original ID incorrectly set to NULL, causing problems in the Translation Editor.<br>This operation corrects the original IDs in the trp_gettext_* tables.<br>Only check this option if you encountered an issue in the Translation Editor where clicking the green pencil did not bring up the gettext string for translation in the left sidebar.<br>Otherwise, please leave this option unchecked because it\'s an intensive operation.'=>'Memperbaiki masalah kasus tepi di mana beberapa string gettext memiliki ID asli yang diatur secara tidak benar ke NULL, menyebabkan masalah di Translation Editor.<br>Operasi ini memperbaiki ID asli di tabel trp_gettext_*.<br>Hanya centang opsi ini jika Anda mengalami masalah di Translation Editor saat mengklik pensil hijau tidak menampilkan string gettext untuk diterjemahkan di bilah sisi kiri.<br>Jika tidak, silakan biarkan opsi ini tidak dicentang karena ini adalah operasi yang intensif.','Optimize Database'=>'Optimalkan Basis Data','TranslatePress Database Updater'=>'TranslatePress Database Updater','Updating TranslatePress tables. Please leave this window open.'=>'Memperbarui tabel TranslatePress. Mohon biarkan jendela ini tetap terbuka.','Open colour picker'=>'Buka pemilih warna','Enabled'=>'Diaktifkan','Disabled'=>'Dinonaktifkan','Write custom CSS here...'=>'Tulis CSS kustom di sini...','Include'=>'Sertakan','Exclude'=>'Kecualikan','Content Restriction Mode'=>'Mode Pembatasan Konten','No languages selected'=>'Tidak ada bahasa yang dipilih','Saving...'=>'Menyimpan...','Saved!'=>'Tersimpan!','Save changes'=>'Simpan perubahan','Revert to last saved values'=>'Kembalikan ke nilai tersimpan terakhir','Revert changes'=>'Kembalikan perubahan','Restoring will revert to the last saved version and discard your current edits.'=>'Memulihkan akan mengembalikan ke versi tersimpan terakhir dan membuang perubahan Anda saat ini.','Revert'=>'Kembalikan','Keep editing'=>'Lanjutkan mengedit','Are you sure you want to apply the <strong>%s</strong> preset?'=>'Apakah Anda yakin ingin menerapkan preset <strong>%s</strong>?','It will override your current settings.'=>'Ini akan mengganti pengaturan Anda saat ini.','Apply preset'=>'Terapkan preset','Apply %s preset'=>'Terapkan prasetel %s','Save failed'=>'Gagal menyimpan','English'=>'Inggris','Spanish'=>'Spanyol','French'=>'Prancis','Minimal Light'=>'Minimal Terang','Dark Overlay'=>'Hamparan Gelap','Brand Blue'=>'Biru Merek','Bordered'=>'Berbingkai','Popup Preview'=>'Pratinjau Popup','User Language Detection Method'=>'Metode Deteksi Bahasa Pengguna','Notification Behavior'=>'Perilaku Notifikasi','Popup Content'=>'Konten Popup','Apply a preset'=>'Terapkan prasetel','Customize Design'=>'Sesuaikan Desain','Language detection'=>'Deteksi Bahasa','Select how the language should be detected for first time visitors.<br>The visitor\'s last displayed language will be remembered through cookies.'=>'Pilih bagaimana bahasa harus dideteksi untuk pengunjung pertama kali.<br>Bahasa terakhir yang ditampilkan pengunjung akan diingat melalui cookie.','Popup display'=>'Tampilan Popup','Conditionally display popup based on language'=>'Tampilkan popup secara kondisional berdasarkan bahasa','Popup Type'=>'Jenis Pop-up','Visitors will be redirected directly when a different preferred language is detected.'=>'Pengunjung akan langsung dialihkan saat bahasa pilihan yang berbeda terdeteksi.','Popup Text'=>'Teks Pop-up','Button Text'=>'Teks Tombol','Close Button Text'=>'Teks Tombol Tutup','Background color'=>'Warna latar belakang','Text color'=>'Warna teks','Button background color'=>'Warna latar belakang tombol','Button hover color'=>'Warna hover tombol','Button text color'=>'Warna teks tombol','Button border radius'=>'Radius sudut tombol','Close icon color'=>'Warna ikon tutup','Overlay color'=>'Warna overlay','Entrance animation'=>'Animasi masuk','Animation'=>'Animasi','Fade'=>'Pudar','Slide from top'=>'Geser dari atas','Slide from right'=>'Geser dari kanan','Slide from bottom'=>'Geser dari bawah','Slide from left'=>'Geser dari kiri','Enable custom CSS'=>'Aktifkan CSS kustom','No names'=>'Tanpa nama','Show flags'=>'Tampilkan bendera','Rectangle (4:3)'=>'Persegi panjang (4:3)','Square (1:1)'=>'Persegi (1:1)','Flag border radius'=>'Radius sudut bendera','Switcher background'=>'Latar belakang pengalih','Switcher hover background'=>'Latar belakang hover pengalih','Switcher text'=>'Teks pengalih','Switcher hover text'=>'Teks hover pengalih','Switcher border'=>'Border pengalih','Switcher border width'=>'Lebar border switcher','Switcher border radius'=>'Radius border switcher','Hover over the language switcher to see it in action!'=>'Arahkan kursor ke pengalih bahasa untuk melihat tampilannya!','Switcher Preview'=>'Pratinjau Pengalih','Enable Floating Switcher'=>'Aktifkan Pengalih Melayang','Switcher is enabled'=>'Pengalih diaktifkan','Switcher is disabled'=>'Pengalih dinonaktifkan','Switcher Type'=>'Jenis Pengalih','Show languages as dropdown'=>'Tampilkan bahasa sebagai dropdown','Show languages side by side'=>'Tampilkan bahasa berdampingan','Background hover color'=>'Warna latar belakang hover','Text hover color'=>'Warna teks hover','Switcher border color'=>'Warna border switcher','Flag and text size'=>'Ukuran bendera dan teks','Flag icons shape'=>'Bentuk ikon bendera','Flag icons border radius'=>'Radius border ikon bendera','Customize Layout'=>'Sesuaikan Tata Letak','Show the small Powered by TranslatePress label in the language switcher.'=>'Tampilkan label kecil Ditenagai oleh TranslatePress di pengalih bahasa.','You have unsaved changes. Leave anyway?'=>'Anda memiliki perubahan yang belum disimpan. Tinggalkan saja?','Switcher animations'=>'Animasi switcher','Transforms the language switcher into a button showing the other available language, not the current one. <br> Only works when there are exactly two languages, the default one and a translation one.'=>'Mengubah pengalih bahasa menjadi tombol yang menampilkan bahasa lain yang tersedia, bukan bahasa saat ini. <br> Hanya berfungsi ketika ada tepat dua bahasa, bahasa default dan bahasa terjemahan.','This option only works when exactly two languages are published.'=>'Opsi ini hanya berfungsi ketika tepat dua bahasa diterbitkan.','Copied!'=>'Disalin!','Copy'=>'Salin','Use shortcode on any page or widget. You can also add the Language Switcher Block in the WP Gutenberg Editor.'=>'Gunakan shortcode di halaman atau widget apa pun. Anda juga dapat menambahkan Blok Pengalih Bahasa di Editor Gutenberg WP.','Shortcode'=>'Shortcode','Additional Settings'=>'Pengaturan Tambahan','Open the language switcher shortcode by clicking on it instead of hovering. <br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. <br> This will affect only the shortcode language switcher.'=>'Buka shortcode pengalih bahasa dengan mengkliknya, bukan dengan mengarahkan kursor. <br> Tutup dengan mengkliknya, mengklik di mana saja di layar, atau menekan tombol escape. <br> Ini hanya akan memengaruhi pengalih bahasa shortcode.','Menu Switcher Layout'=>'Tata Letak Pengalih Menu','Go to <a href="/wp-admin/nav-menus.php">Appearance → Menus</a> to add languages to the Language Switcher in any menu.<br> <a href="https://translatepress.com/docs/settings/language-switcher/?utm_source=tp-language-switcher&utm_medium=client-site&utm_campaign=ls-menu-item#menu-switcher" target="_blank">Learn more in our documentation.</a>'=>'Buka <a href="/wp-admin/nav-menus.php">Tampilan → Menu</a> untuk menambahkan bahasa ke Pengalih Bahasa di menu apa pun.<br> <a href="https://translatepress.com/docs/settings/language-switcher/?utm_source=tp-language-switcher&utm_medium=client-site&utm_campaign=ls-menu-item#menu-switcher" target="_blank">Pelajari lebih lanjut di dokumentasi kami.</a>','Choose in which languages to show the block.'=>'Pilih bahasa untuk menampilkan blok.','Choose from which languages the block is excluded.'=>'Pilih bahasa yang mengecualikan blok.','Select language(s)'=>'Pilih bahasa','TranslatePress Language Restriction'=>'Pembatasan Bahasa TranslatePress','Language restrictions cannot be saved on a top-level Classic block. Convert it to blocks or place it inside a Group block first.'=>'Pembatasan bahasa tidak dapat disimpan pada blok Klasik tingkat atas. Ubah ke blok atau letakkan di dalam blok Grup terlebih dahulu.','page 1 of 3of'=>'/','Untranslated in this languagein'=>'dalam','Verbiage for the DeepL Pro Add-onAddons tab'=>'Tab pengaya','Verbiage for the DeepL Pro Add-onTranslatePress Pro Add-on'=>'TranslatePress Pro Add-on','block titleLanguage Switcher'=>'Pengalih Bahasa','block descriptionDisplays the Language Switcher.'=>'Menampilkan Pengalih Bahasa.','block keywordLanguage Switcher'=>'Pengalih Bahasa','block keywordTranslate'=>'Terjemahkan','block keywordTranslatePress'=>'TranslatePress','block keywordLanguage Names'=>'Nama Bahasa','block keywordFlags'=>'Bendera']];